void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_line *line2 = NULL;
    struct gpiod_line *line3 = NULL;
    struct gpiod_chip *chip;
    int ret;

    // Set up signal handler for graceful exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip (BCM2835 is the default for Raspberry Pi)
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Configure GPIO 2 as output
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        fprintf(stderr, "Failed to get line for GPIO 2\n");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line2, "gpio2-out", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line GPIO 2 as output: %s\n", strerror(-ret));
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure GPIO 3 as output
    line3 = gpiod_chip_get_line(chip, GPIO_PIN_3);
    if (!line3) {
        fprintf(stderr, "Failed to get line for GPIO 3\n");
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line3, "gpio3-out", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line GPIO 3 as output: %s\n", strerror(-ret));
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        return 1;
    }

    while (running) {
        // Toggle GPIO 2
        gpiod_line_set_value(line2, 1);
        printf("GPIO 2 set to 1\n");
        usleep(INTERVAL);

        gpiod_line_set_value(line2, 0);
        printf("GPIO 2 set to 0\n");
        usleep(INTERVAL);

        // Toggle GPIO 3
        gpiod_line_set_value(line3, 1);
        printf("GPIO 3 set to 1\n");
        usleep(INTERVAL);

        gpiod_line_set_value(line3, 0);
        printf("GPIO 3 set to 0\n");
        usleep(INTERVAL);
    }

    // Clean up
    gpiod_line_release(line2);
    gpiod_line_release(line3);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <gpiod.h>
#include <signal.h>

#define GPIO_PIN 2
#define INTERVAL 5
#define MAX_RETRIES 3

typedef struct {
    struct gpiod_line *line;
    int running;
} gpio_state;

void cleanup(gpio_state *state) {
    if (state->line) {
        gpiod_line_release(state->line);
    }
    printf("Cleanup complete.\n");
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Interrupt received. Exiting...\n");
        exit(EXIT_SUCCESS);
    }
}

int main() {
    gpio_state state = {0};
    int ret;
    int retry = 0;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO line
    while (retry < MAX_RETRIES) {
        state.line = gpiod_line_get("gpiochip0", GPIO_PIN);
        if (state.line) {
            break;
        }
        fprintf(stderr, "Failed to get GPIO line. Retrying...\n");
        retry++;
        sleep(1);
    }

    if (!state.line) {
        fprintf(stderr, "Failed to get GPIO line after %d retries. Exiting.\n", MAX_RETRIES);
        exit(EXIT_FAILURE);
    }

    // Set the line as output
    ret = gpiod_line_request_output(state.line, "gpio_out", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        cleanup(&state);
        exit(EXIT_FAILURE);
    }

    state.running = 1;

    while (state.running) {
        // Toggle the output state
        int current_value = gpiod_line_get_value(state.line);
        if (current_value < 0) {
            fprintf(stderr, "Failed to read GPIO line value: %s\n", strerror(errno));
            cleanup(&state);
            exit(EXIT_FAILURE);
        }

        int new_value = (current_value == 0) ? 1 : 0;
        ret = gpiod_line_set_value(state.line, new_value);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO line value: %s\n", strerror(errno));
            cleanup(&state);
            exit(EXIT_FAILURE);
        }

        printf("GPIO %d set to %d\n", GPIO_PIN, new_value);
        sleep(INTERVAL);
    }

    cleanup(&state);
    exit(EXIT_SUCCESS);
}

