#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADS1115_CONFIG_REGISTER 0x01
#define ADS1115_POINTER 0x00
#define ADS1115_CONFIG_MUX_AIN0_AIN1 0x40
#define ADS1115_CONFIG_PGA_6_144V 0x00
#define ADS1115_CONFIG_MODE_SINGLE 0x8000
#define ADS1115_CONFIG_RATE_860SPS 0x0200
#define ADS1115_CONFIG_GAIN 0x00
#define ADS1115_CONFIG_DEFAULT (ADS1115_CONFIG_MUX_AIN0_AIN1 | ADS1115_CONFIG_PGA_6_144V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_RATE_860SPS)

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

int open_i2c_bus(const char *device) {
    int file_desc;
    if ((file_desc = open(device, O_RDWR)) < 0) {
        perror("Failed to open the I2C bus");
        return -1;
    }
    return file_desc;
}

int i2c_write_register(int file_desc, uint8_t reg, uint16_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value & 0xFF;
    if (write(file_desc, buffer, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int i2c_read_register(int file_desc, uint8_t reg, uint16_t *value) {
    uint8_t buffer[1];
    buffer[0] = reg;
    if (write(file_desc, buffer, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    if (read(file_desc, buffer, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    *value = buffer[0];
    return 0;
}

void close_i2c_bus(int file_desc) {
    if (close(file_desc) < 0) {
        perror("Failed to close I2C bus");
    }
}

int main() {
    int i2c_file = -1;
    uint16_t config = ADS1115_CONFIG_DEFAULT;
    uint16_t reading = 0;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_file = open_i2c_bus(I2C_BUS);
    if (i2c_file < 0) {
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    if (ioctl(i2c_file, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close_i2c_bus(i2c_file);
        exit(EXIT_FAILURE);
    }

    // Write configuration register
    if (i2c_write_register(i2c_file, ADS1115_CONFIG_REGISTER, config) < 0) {
        close_i2c_bus(i2c_file);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (running) {
        // Read the ADC value
        if (i2c_read_register(i2c_file, ADS1115_POINTER, &reading) < 0) {
            close_i2c_bus(i2c_file);
            exit(EXIT_FAILURE);
        }

        // Print the reading
        printf("ADC Reading: %d\n", reading);

        // Sleep for 0.5 seconds
        usleep(500000);
    }

    // Clean up
    close_i2c_bus(i2c_file);
    return 0;
}

