#define I2C_BUS "/dev/i2c-1"
#define MLX90614_ADDR 0x5a
#define MLX90614_AMBIENT_REGISTER 0x06
#define MLX90614_OBJECT_REGISTER 0x07
#define MLX90614_AMBIENT_SIZE 2
#define MLX90614_OBJECT_SIZE 2

typedef struct {
    int fd;
    int running;
} i2c_context;

void cleanup(i2c_context *ctx) {
    if (ctx->fd >= 0) {
        close(ctx->fd);
        ctx->fd = -1;
    }
    ctx->running = 0;
}

void signal_handler(int signal) {
    cleanup(NULL);
    exit(EXIT_FAILURE);
}

int i2c_init(i2c_context *ctx) {
    ctx->fd = open(I2C_BUS, O_RDWR);
    if (ctx->fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(ctx->fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(ctx->fd);
        return -1;
    }

    return 0;
}

int read_mlxsensor(i2c_context *ctx, uint16_t *ambient, uint16_t *object) {
    uint8_t buffer[MLX90614_AMBIENT_SIZE + MLX90614_OBJECT_SIZE];
    ssize_t bytes_read;

    if (read(ctx->fd, buffer, MLX90614_AMBIENT_SIZE + MLX90614_OBJECT_SIZE) < 0) {
        perror("Failed to read from MLX90614");
        return -1;
    }

    *ambient = (buffer[0] << 8) | buffer[1];
    *object = (buffer[2] << 8) | buffer[3];

    return 0;
}

void print_measurement(double ambient, double object) {
    printf("Ambient: %.2f°C | Object: %.2f°C\n", ambient, object);
}

int main() {
    i2c_context ctx = { .fd = -1, .running = 1 };
    uint16_t ambient, object;
    double ambient_temp, object_temp;
    struct timespec sleep_time = { .tv_sec = 5, .tv_nsec = 0 };
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (i2c_init(&ctx) < 0) {
        fprintf(stderr, "MLX90614 device not found or not accessible.\n");
        exit(EXIT_FAILURE);
    }

    while (ctx.running) {
        ret = read_mlxsensor(&ctx, &ambient, &object);
        if (ret < 0) {
            fprintf(stderr, "Error reading MLX90614, exiting.\n");
            cleanup(&ctx);
            exit(EXIT_FAILURE);
        }

        ambient_temp = (double)(ambient - 27315) / 100.0;
        object_temp = (double)(object - 27315) / 100.0;

        print_measurement(ambient_temp, object_temp);

        nanosleep(&sleep_time, NULL);
    }

    cleanup(&ctx);
    exit(EXIT_SUCCESS);
}

