#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define INTERVAL 500000  // 0.5 seconds in microseconds

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        return 1;
    }

    // Set up GPIO 18 as PWM output
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n", GPIO_PIN, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMFrequency(GPIO_PIN, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d: %s\n", GPIO_PIN, strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for termination
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        // Set PWM duty cycle (0-100%)
        int duty_cycle = 50;  // 50% duty cycle
        if (gpioPWM(GPIO_PIN, duty_cycle) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d: %s\n", GPIO_PIN, strerror(errno));
            gpioTerminate();
            return 1;
        }

        // Report the state
        printf("PWM applied to GPIO %d with duty cycle %d%%\n", GPIO_PIN, duty_cycle);
        fflush(stdout);

        // Wait for the interval
        usleep(INTERVAL);
    }

    // Clean up
    gpioPWM(GPIO_PIN, 0);  // Turn off PWM
    gpioTerminate();

    return 0;
}

