            gpiod_line_release(echo_line);
            exit(EXIT_FAILURE);
        }

        // Wait for 10 microseconds
        usleep(10000);

        // Set TRIG pin back to low
        ret = gpiod_line_set_value(trig_line, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set TRIG pin %d to low: %s\n", TRIG_PIN, strerror(-ret));
            gpiod_line_release(trig_line);
            gpiod_line_release(echo_line);
            exit(EXIT_FAILURE);
        }

        // Wait for ECHO pin to go high
        timeout = 0;
        while (gpiod_line_get_value(echo_line) == 0 && timeout < 100000) {
            usleep(10);
            timeout++;
        }

        if (timeout >= 100000) {
            fprintf(stderr, "ECHO pin did not go high, no response from sensor\n");
            gpiod_line_release(trig_line);
            gpiod_line_release(echo_line);
            continue;
