#include <string.h>
#include <errno.h>
#include <signal.h>
#include <stdint.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define CMD_WRITE 0x00
#define CMD_READ 0x01
#define CMD_CONFIG 0x01
#define CMD_POINTER 0x03
#define CMD_CONVERT 0x00
#define CMD_CONTINUOUS 0x80
#define CMD_GAIN 0x00
#define CMD_DATA 0x00
#define CMD_DATA_SIZE 2
#define CMD_DELAY 5000000  // 5 seconds in microseconds

#define MAX_RETRIES 3

typedef struct {
    int fd;
    int retry_count;
} i2c_dev;

void i2c_init(i2c_dev *dev) {
    char filename[256];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    dev->fd = open(filename, O_RDWR);
    if (dev->fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(dev->fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(dev->fd);
        exit(EXIT_FAILURE);
    }
}

void i2c_close(i2c_dev *dev) {
    close(dev->fd);
}

int i2c_read(i2c_dev *dev, uint16_t *value) {
    uint8_t reg = CMD_POINTER | CMD_READ;
    uint8_t buffer[CMD_DATA_SIZE];

    if (write(dev->fd, &reg, 1) < 0) {
        perror("Failed to write to I2C device");
        return -1;
    }

    if (read(dev->fd, buffer, CMD_DATA_SIZE) < 0) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *value = (buffer[0] << 8) | buffer[1];
    return 0;
}

void i2c_config(i2c_dev *dev) {
    uint8_t reg = CMD_CONFIG;
    uint8_t config = CMD_CONTINUOUS | CMD_GAIN;

    if (write(dev->fd, &reg, 1) < 0) {
        perror("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }

    if (write(dev->fd, &config, 1) < 0) {
        perror("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }
}

void signal_handler(int signal) {
    printf("\nInterrupt received. Exiting...\n");
    exit(EXIT_SUCCESS);
}

int main() {
    i2c_dev dev;
    uint16_t value;
    int retry_count = 0;
    int result;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (i2c_init(&dev) < 0) {
        fprintf(stderr, "I2C device not found or not accessible.\n");
        exit(EXIT_FAILURE);
    }

    i2c_config(&dev);

    while (1) {
        result = i2c_read(&dev, &value);
        if (result < 0) {
            retry_count++;
            if (retry_count >= MAX_RETRIES) {
                fprintf(stderr, "Failed to read ADC after %d retries. Exiting.\n", MAX_RETRIES);
                i2c_close(&dev);
                exit(EXIT_FAILURE);
            }
            usleep(CMD_DELAY);
            continue;
        }

        retry_count = 0;

        if (value > 0x0FFF) {
            fprintf(stderr, "Invalid ADC reading: %04X. Rejecting.\n", value);
            usleep(CMD_DELAY);
            continue;
        }

        printf("ADC Reading: %04X\n", value);
        usleep(CMD_DELAY);
    }

    i2c_close(&dev);
    return 0;
}

