#define SI7021_ADDR 0x40
#define SI7021_HUMIDITY_REGISTER 0xE5
#define SI7021_TEMPERATURE_REGISTER 0xF3
#define SI7021_READING_TIMEOUT 1000  // milliseconds

typedef struct {
    int humidity;
    int temperature;
} si7021_reading;

// Function to read a 16-bit little-endian value from I2C
int i2c_read_word(int fd, int reg) {
    unsigned char buf[2];
    int ret;

    if (ioctl(fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write I2C register");
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        perror("Failed to read I2C data");
        return -1;
    }

    return (buf[0] << 8) | buf[1];
}

// Function to convert humidity reading to percentage
int si7021_convert_humidity(int raw) {
    int humidity = (raw * 125) / 65536;
    if (humidity < 0) humidity = 0;
    if (humidity > 100) humidity = 100;
    return humidity;
}

// Function to convert temperature reading to Celsius
float si7021_convert_temperature(int raw) {
    float temp = (raw * 175.72) / 65536 - 46.85;
    return temp;
}

// Function to check if a reading is valid
int is_valid_reading(int humidity, float temperature) {
    return humidity >= 0 && humidity <= 100 && temperature >= -40.0 && temperature <= 125.0;
}

// Function to handle signals and clean up
void handle_signal(int sig) {
    printf("\nReceived signal %d, exiting...\n", sig);
    exit(EXIT_FAILURE);
}

int main() {
    int i2c_fd = -1;
    int ret;
    struct sigaction sa;
    si7021_reading reading;
    time_t last_print_time = 0;

    // Set up signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to set up SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set up SIGTERM handler");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR | O_NONBLOCK);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Check if device is present
    if (ioctl(i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        perror("SI7021 device not found or not responding");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Wait for 5 seconds
        time_t current_time = time(NULL);
        if (current_time - last_print_time >= 5) {
            last_print_time = current_time;

            // Read humidity
            int humidity_raw = i2c_read_word(i2c_fd, SI7021_HUMIDITY_REGISTER);
            if (humidity_raw < 0) {
                fprintf(stderr, "Failed to read humidity\n");
                continue;
            }

            // Read temperature
            int temperature_raw = i2c_read_word(i2c_fd, SI7021_TEMPERATURE_REGISTER);
            if (temperature_raw < 0) {
                fprintf(stderr, "Failed to read temperature\n");
                continue;
