            // Convert readings
            reading.humidity = si7021_convert_humidity(humidity_raw);
            reading.temperature = si7021_convert_temperature(temperature_raw);

            // Check validity
            if (!is_valid_reading(reading.humidity, reading.temperature)) {
                fprintf(stderr, "Invalid reading: humidity=%d%%, temperature=%.2f°C\n",
