    return file_desc;
}

int i2c_write_register(int file_desc, uint8_t reg, uint16_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value & 0xFF;
    if (write(file_desc, buffer, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int i2c_read_register(int file_desc, uint8_t reg, uint16_t *value) {
    uint8_t buffer[1];
    buffer[0] = reg;
    if (write(file_desc, buffer, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    if (read(file_desc, buffer, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    *value = buffer[0];
    return 0;
}

int i2c_read_adc(int file_desc, uint16_t *value) {
    uint8_t buffer[2];
    if (write(file_desc, &ADS1115_POINTER_CONVERT, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    if (read(file_desc, buffer, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }
    *value = (buffer[0] << 8) | buffer[1];
    return 0;
}

