#define BAUD_RATE B9600
#define DEVICE_PATH "/dev/ttyAMA0"

int serial_fd = -1;

void cleanup(int sig) {
    if (serial_fd >= 0) {
        close(serial_fd);
    }
    exit(EXIT_FAILURE);
}

int open_serial_port(const char *device_path) {
    int fd = open(device_path, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        perror("Failed to open serial port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Failed to get terminal attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag &= ~PARENB;        // No parity
    tty.c_cflag &= ~CSTOPB;        // 1 stop bit
    tty.c_cflag &= ~CSIZE;         // Clear character size mask
    tty.c_cflag |= CS8;            // 8 bits per character
    tty.c_cflag &= ~CRTSCTS;       // No hardware flow control
    tty.c_cflag |= CREAD | CLOCAL; // Enable receiver, ignore modem control lines

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG); // No canonical mode, no echo
    tty.c_oflag &= ~OPOST; // Output processing off

    tty.c_cc[VTIME] = 0;     // Wait 0 seconds for input
    tty.c_cc[VMIN] = 1;      // Read at least 1 character

    if (tcsetattr(fd, TCSAFLUSH, &tty) != 0) {
        perror("Failed to set terminal attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    serial_fd = open_serial_port(DEVICE_PATH);
    if (serial_fd < 0) {
        return EXIT_FAILURE;
    }

    char buffer[256];
    ssize_t bytes_read;

    while (1) {
        bytes_read = read(serial_fd, buffer, sizeof(buffer) - 1);
        if (bytes_read < 0) {
            perror("Read error");
            cleanup(0);
        } else if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("Received: %s", buffer);
            fflush(stdout);
        }

        // Sleep briefly to avoid busy-waiting
        usleep(100000);
    }

    return EXIT_SUCCESS;
}

