typedef struct {
    struct gpiod_line *line2;
    struct gpiod_line *line3;
    int running;
} gpio_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal, shutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void cleanup(gpio_state *state) {
    if (state->line2) {
        gpiod_line_release(state->line2);
    }
    if (state->line3) {
        gpiod_line_release(state->line3);
    }
    printf("GPIO resources released.\n");
}

int init_gpio(gpio_state *state) {
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    state->line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!state->line2) {
        perror("Failed to get GPIO line 2");
        gpiod_chip_close(chip);
        return -1;
    }

    state->line3 = gpiod_chip_get_line(chip, GPIO_PIN_3);
    if (!state->line3) {
        perror("Failed to get GPIO line 3");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(state->line2, "gpio2-out", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line 2 as output");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(state->line3, "gpio3-out", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line 3 as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

void set_gpio_state(gpio_state *state, int pin, int value) {
    if (pin == GPIO_PIN_2) {
        if (value != 0 && value != 1) {
            fprintf(stderr, "Invalid value for GPIO 2: %d\n", value);
            return;
        }
        gpiod_line_set_value(state->line2, value);
    } else if (pin == GPIO_PIN_3) {
        if (value != 0 && value != 1) {
            fprintf(stderr, "Invalid value for GPIO 3: %d\n", value);
            return;
        }
        gpiod_line_set_value(state->line3, value);
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", pin);
    }
}

