    gpio_state state = {0};
    int value = 0;
    struct sigaction sa;

    // Set up signal handler
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        return EXIT_FAILURE;
    }

    if (init_gpio(&state) != 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    state.running = 1;
    while (state.running) {
        value = 1 - value;  // Toggle between 0 and 1
        set_gpio_state(&state, GPIO_PIN_2, value);
        set_gpio_state(&state, GPIO_PIN_3, value);
        printf("GPIO 2: %d, GPIO 3: %d\n", value, value);
        usleep(INTERVAL);
    }

    cleanup(&state);
    return EXIT_SUCCESS;
}

