#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PINS 5
#define GPIO_PIN_LIST {4, 17, 18, 22, 27}

typedef struct {
    struct gpiod_line *lines[GPIO_PINS];
    int running;
} gpio_state;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("\nReceived signal, shutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void setup_gpio(gpio_state *state) {
    struct gpiod_chip *chip;
    int i;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    for (i = 0; i < GPIO_PINS; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_PIN_LIST[i]);
        if (!line) {
            perror("Failed to get GPIO line");
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_request_output(line, "gpio_output", 0) < 0) {
            perror("Failed to request GPIO line as output");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        state->lines[i] = line;
    }

    state->running = 1;
}

void cleanup_gpio(gpio_state *state) {
    int i;

    for (i = 0; i < GPIO_PINS; i++) {
        if (state->lines[i]) {
            gpiod_line_release(state->lines[i]);
        }
    }

    if (state->running) {
        gpiod_chip_close(chip);
    }
}

void toggle_gpio(gpio_state *state) {
    int i;
    for (i = 0; i < GPIO_PINS; i++) {
        int value = gpiod_line_get_value(state->lines[i]);
        if (gpiod_line_set_value(state->lines[i], !value) < 0) {
            perror("Failed to set GPIO value");
            exit(EXIT_FAILURE);
        }
        printf("GPIO %d: %d\n", GPIO_PIN_LIST[i], !value);
    }
}

int main() {
    gpio_state state;
    struct sigaction sa;

    setup_gpio(&state);

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        cleanup_gpio(&state);
        exit(EXIT_FAILURE);
    }

    while (state.running) {
        toggle_gpio(&state);
        usleep(50000);  // 0.05 seconds
    }

    cleanup_gpio(&state);
    return 0;
}

