#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x44
#define REG_CONFIG 0x01
#define REG_DATA 0x00

int main() {
    int file_desc;
    char *filename = I2C_BUS;
    int err;

    // Open I2C bus
    if ((file_desc = open(filename, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        exit(EXIT_FAILURE);
    }

    // Set the I2C slave address
    if (ioctl(file_desc, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(file_desc);
        exit(EXIT_FAILURE);
    }

    // Read the configuration register to ensure it's in default mode
    unsigned char config_reg[1] = {REG_CONFIG};
    if (write(file_desc, config_reg, 1) != 1) {
        perror("Failed to write to I2C configuration register");
        close(file_desc);
        exit(EXIT_FAILURE);
    }

    // Read the data register
    unsigned char data[2] = {0};
    if (read(file_desc, data, 2) != 2) {
        perror("Failed to read from I2C data register");
        close(file_desc);
        exit(EXIT_FAILURE);
    }

    // Convert the 16-bit data to a 16-bit integer
    uint16_t raw_data = (data[0] << 8) | data[1];

    // Convert raw data to lux (assuming default configuration)
    // OPT3001 datasheet: 1 lux = 1000000 / 16384 = 61.03515625
    double lux = (double)raw_data * 61.03515625;

    // Print the result
    printf("Lux: %.2f\n", lux);

    // Close the I2C bus
    close(file_desc);

    return 0;
}

