    int ret;

    // Initialize line request configuration
    memset(&req, 0, sizeof(req));
    req.consumer = "gpio_output";
    req.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;

    // Open GPIO line 17
    line17 = gpiod_line_get("gpiochip0", GPIO_PIN_17);
    if (!line17) {
        fprintf(stderr, "Failed to get GPIO line 17\n");
        return EXIT_FAILURE;
    }

    // Request line 17 as output
    ret = gpiod_line_request_output(line17, "output", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line 17 as output: %s\n", strerror(errno));
        gpiod_line_put(line17);
        return EXIT_FAILURE;
    }

    // Open GPIO line 18
    line18 = gpiod_line_get("gpiochip0", GPIO_PIN_18);
    if (!line18) {
        fprintf(stderr, "Failed to get GPIO line 18\n");
        gpiod_line_put(line17);
        return EXIT_FAILURE;
