#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <termios.h>
#include <sys/ioctl.h>
#include <signal.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE B115200
#define TIMEOUT_MS 1000

int uart_fd = -1;

void cleanup(int sig) {
    if (uart_fd >= 0) {
        close(uart_fd);
    }
    exit(EXIT_FAILURE);
}

int open_uart_port(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        perror("Failed to open UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Failed to get terminal attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag &= ~PARENB;        // No parity
    tty.c_cflag &= ~CSTOPB;        // 1 stop bit
    tty.c_cflag &= ~CSIZE;         // Clear character size mask
    tty.c_cflag |= CS8;            // 8 bits per character

    tty.c_cflag &= ~CRTSCTS;       // No hardware flow control
    tty.c_cflag |= CREAD | CLOCAL; // Enable receiver, ignore modem control lines

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG); // No canonical mode
    tty.c_oflag &= ~OPOST;         // No output processing

    tty.c_cc[VMIN] = 0;            // Wait for at least 0 characters
    tty.c_cc[VTIME] = 10;          // 10 tenths of a second = 1 second timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Failed to set terminal attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_uart_data(int fd, char *buffer, size_t size) {
    ssize_t n = read(fd, buffer, size);
    if (n < 0) {
        perror("UART read error");
        return -1;
    } else if (n == 0) {
        return 0; // No data received
    }
    return n;
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    uart_fd = open_uart_port(UART_DEVICE);
    if (uart_fd < 0) {
        fprintf(stderr, "UART device not found or inaccessible\n");
        return EXIT_FAILURE;
    }

    char buffer[128];
    ssize_t bytes_read;

    // Attempt to read data with timeout
    bytes_read = read_uart_data(uart_fd, buffer, sizeof(buffer));
    if (bytes_read <= 0) {
        fprintf(stderr, "No data received from device\n");
        return EXIT_FAILURE;
    }

    buffer[bytes_read] = '\0';
    printf("Received: %s\n", buffer);

    close(uart_fd);
    return EXIT_SUCCESS;
}

