#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <gpiod.h>
#include <signal.h>

#define GPIO_PIN 2
#define CYCLE_COUNT 3
#define CYCLE_DELAY 60

volatile int exit_flag = 0;

void handle_signal(int sig) {
    exit_flag = 1;
}

int main() {
    struct gpiod_line *line;
    struct gpiod_line_request_config req_config;
    int cycle = 0;
    int ret;

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize libgpiod
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Configure line
    req_config = gpiod_line_request_config_default();
    req_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    req_config.default_value = 0;

    line = gpiod_chip_request_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request(line, &req_config);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (cycle < CYCLE_COUNT && !exit_flag) {
        // Set output to high
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO high: %s\n", strerror(errno));
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN);
        sleep(CYCLE_DELAY);

        // Set output to low
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO low: %s\n", strerror(errno));
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN);
        sleep(CYCLE_DELAY);

        cycle++;
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

