#define PWM_FREQ 1000
#define PWM_RANGE 100
#define INTERVAL 5000  // 5 seconds in milliseconds

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

void setup_pwm(int gpio, int frequency, int range) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio.\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(gpio, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output.\n", gpio);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetPWMFrequency(gpio, frequency) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d.\n", gpio);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetPWMRange(gpio, range) < 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d.\n", gpio);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void set_pwm_values(int gpio1, int gpio2, int gpio3, int value) {
    if (gpioPWM(gpio1, value) < 0) {
        fprintf(stderr, "Failed to set PWM value for GPIO %d.\n", gpio1);
    }
    if (gpioPWM(gpio2, value) < 0) {
        fprintf(stderr, "Failed to set PWM value for GPIO %d.\n", gpio2);
    }
    if (gpioPWM(gpio3, value) < 0) {
        fprintf(stderr, "Failed to set PWM value for GPIO %d.\n", gpio3);
    }
}

void cleanup() {
    gpioTerminate();
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_pwm(GPIO_PWM_17, PWM_FREQ, PWM_RANGE);
    setup_pwm(GPIO_PWM_18, PWM_FREQ, PWM_RANGE);
    setup_pwm(GPIO_PWM_27, PWM_FREQ, PWM_RANGE);

    int value = 0;
    int step = 1;

    while (running) {
        for (int i = 0; i < 100; i++) {
            set_pwm_values(GPIO_PWM_17, GPIO_PWM_18, GPIO_PWM_27, value);
            printf("PWM value: %d\n", value);
            fflush(stdout);
            usleep(10000);  // 10 ms
            value += step;
            if (value >= PWM_RANGE || value <= 0) {
                step = -step;
            }
        }

        // Wait for 5 seconds
        usleep(INTERVAL * 1000);
    }

    cleanup();
    return 0;
}

