    if (!dir) {
        fprintf(stderr, "Failed to open 1-wire directory: %s\n", strerror(errno));
        return -1;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_LNK) {
            snprintf(path, sizeof(path), "%s/%s/w1_slave", DS18B20_DEVICE_PATH, entry->d_name);
            int fd = open(path, O_RDONLY);
            if (fd >= 0) {
