                        snprintf(sensor->rom_id, DS18B20_ROM_ID_SIZE, "%s", entry->d_name);
                        snprintf(sensor->device_path, sizeof(sensor->device_path), "%s/%s", DS18B20_DEVICE_PATH, entry->d_name);
                        close(fd);
