#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define HTU21D_READ_TEMP 0xE3
#define HTU21D_READ_HUM 0xE5
#define HTU21D_WRITE_CTRL 0xF3
#define HTU21D_WRITE_STATUS 0xF2
#define HTU21D_STATUS_REG 0xF6
#define HTU21D_STATUS_BUSY 0x80

typedef struct {
    int humidity;
    int temperature;
} sensor_reading;

int i2c_fd = -1;
volatile int running = 1;

void cleanup(int sig) {
    running = 0;
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_FAILURE);
}

int i2c_init() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_TEN, 0) < 0) {
        perror("Failed to set 10-bit addressing");
        close(fd);
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    i2c_fd = fd;
    return 0;
}

int read_sensor(sensor_reading *reading) {
    uint8_t cmd = HTU21D_READ_HUM;
    if (write(i2c_fd, &cmd, 1) != 1) {
        perror("Failed to write command to HTU21D");
        return -1;
    }

    // Wait for measurement to complete
    uint8_t status;
    do {
        if (read(i2c_fd, &status, 1) != 1) {
            perror("Failed to read status register");
            return -1;
        }
    } while ((status & HTU21D_STATUS_BUSY) != 0);

    // Read humidity
    if (write(i2c_fd, &HTU21D_READ_HUM, 1) != 1) {
        perror("Failed to write command to HTU21D");
        return -1;
    }

    uint8_t hum_data[3];
    if (read(i2c_fd, hum_data, 3) != 3) {
        perror("Failed to read humidity data");
        return -1;
    }

    uint16_t humidity = (uint16_t)(hum_data[0] << 8 | hum_data[1]);
    humidity = (humidity >> 4) & 0x0FFF;
    reading->humidity = (int)(humidity * 100.0 / 65535.0);

    // Read temperature
    if (write(i2c_fd, &HTU21D_READ_TEMP, 1) != 1) {
        perror("Failed to write command to HTU21D");
        return -1;
    }

    if (read(i2c_fd, hum_data, 3) != 3) {
        perror("Failed to read temperature data");
        return -1;
    }

    uint16_t temp = (uint16_t)(hum_data[0] << 8 | hum_data[1]);
    temp = (temp >> 4) & 0x0FFF;
    reading->temperature = (int)(temp * 175.0 / 65535.0 - 46.85);

    return 0;
}

int validate_reading(sensor_reading *reading) {
    if (reading->humidity < 0 || reading->humidity > 100) {
        fprintf(stderr, "Invalid humidity reading: %d\n", reading->humidity);
        return -1;
    }

    if (reading->temperature < -40 || reading->temperature > 125) {
        fprintf(stderr, "Invalid temperature reading: %d\n", reading->temperature);
        return -1;
    }

    return 0;
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (i2c_init() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return EXIT_FAILURE;
    }

    sensor_reading reading;
    time_t last_print = time(NULL);

    while (running) {
        if (read_sensor(&reading) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            cleanup(0);
