#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define ADXL345_REGISTER_ADDR 0x32  // X-axis acceleration register
#define ADXL345_REGISTER_COUNT 6    // 3 axes, 2 bytes each

int i2c_fd = -1;
volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void close_i2c() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

void i2c_init() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close_i2c();
        exit(EXIT_FAILURE);
    }
}

void read_adxl345() {
    unsigned char reg_addr = ADXL345_REGISTER_ADDR;
    unsigned char buffer[ADXL345_REGISTER_COUNT];

    if (write(i2c_fd, &reg_addr, 1) < 0) {
        perror("Failed to write register address");
        return;
    }

    if (read(i2c_fd, buffer, ADXL345_REGISTER_COUNT) < 0) {
        perror("Failed to read from I2C device");
        return;
    }

    int x = (buffer[0] << 8) | buffer[1];
    int y = (buffer[2] << 8) | buffer[3];
    int z = (buffer[4] << 8) | buffer[5];

    printf("X: %d, Y: %d, Z: %d\n", x, y, z);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_init();

    while (running) {
        read_adxl345();
        usleep(100000);  // 0.1 seconds
    }

    close_i2c();
    return 0;
}

