#define GPIO_PIN_17 17
#define GPIO_PIN_22 22
#define GPIO_PIN_23 23
#define GPIO_PIN_24 24

#define DHT22_PIN_COUNT 4

typedef struct {
    struct gpiod_line *data_line;
    struct gpiod_line *power_line;
    struct gpiod_line *clock_line;
    struct gpiod_line *trig_line;
} DHT22_GPIO;

int dht22_init_gpio(struct gpiod_chip *chip, DHT22_GPIO *gpio) {
    gpio->data_line = gpiod_chip_get_line(chip, GPIO_PIN_22);
    if (!gpio->data_line) {
        fprintf(stderr, "Failed to get data line\n");
        return -1;
    }

    gpio->power_line = gpiod_chip_get_line(chip, GPIO_PIN_23);
    if (!gpio->power_line) {
        fprintf(stderr, "Failed to get power line\n");
        return -1;
    }

    gpio->clock_line = gpiod_chip_get_line(chip, GPIO_PIN_24);
    if (!gpio->clock_line) {
        fprintf(stderr, "Failed to get clock line\n");
        return -1;
    }

    gpio->trig_line = gpiod_chip_get_line(chip, GPIO_PIN_17);
    if (!gpio->trig_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        return -1;
    }

    if (gpiod_line_request_output(gpio->data_line, "dht22_data", GPIO_ACTIVE_LOW) < 0) {
        fprintf(stderr, "Failed to request data line\n");
        return -1;
    }

    if (gpiod_line_request_output(gpio->power_line, "dht22_power", GPIO_ACTIVE_LOW) < 0) {
        fprintf(stderr, "Failed to request power line\n");
        return -1;
    }

    if (gpiod_line_request_output(gpio->clock_line, "dht22_clock", GPIO_ACTIVE_LOW) < 0) {
        fprintf(stderr, "Failed to request clock line\n");
        return -1;
    }

    if (gpiod_line_request_output(gpio->trig_line, "dht22_trig", GPIO_ACTIVE_LOW) < 0) {
        fprintf(stderr, "Failed to request trigger line\n");
        return -1;
    }

    return 0;
}

void dht22_deinit_gpio(DHT22_GPIO *gpio) {
    gpiod_line_release(gpio->data_line);
    gpiod_line_release(gpio->power_line);
    gpiod_line_release(gpio->clock_line);
    gpiod_line_release(gpio->trig_line);
}

int dht22_read_data(DHT22_GPIO *gpio, int *temperature, int *humidity) {
    int data[5] = {0};

    // Power on the DHT22
    gpiod_line_set_value(gpio->power_line, 1);
    usleep(1000);

    // Trigger the DHT22
    gpiod_line_set_value(gpio->trig_line, 1);
    usleep(1000);
    gpiod_line_set_value(gpio->trig_line, 0);

    // Wait for response
    usleep(1000);

    // Read data
    int i = 0;
    while (i < 40) {
        while (gpiod_line_get_value(gpio->data_line) == 1) {
            usleep(1);
        }

        // Wait for the line to go low
        while (gpiod_line_get_value(gpio->data_line) == 0) {
            usleep(1);
        }

        // Read the data bit
        if (gpiod_line_get_value(gpio->data_line) == 1) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }

        i++;
    }

    // Power off the DHT22
    gpiod_line_set_value(gpio->power_line, 0);

    // Check if the checksum is valid
    if (data[4] != (data[0] + data[1] + data[2] + data[3]) & 0xFF) {
        fprintf(stderr, "Checksum error\n");
        return -1;
    }

    *temperature = (data[2] << 8) | data[3];
    *humidity = (data[0] << 8) | data[1];

    return 0;
}

int main() {
    struct gpiod_chip *chip;
    DHT22_GPIO gpio;
    int temperature, humidity;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    if (dht22_init_gpio(chip, &gpio) < 0) {
        fprintf(stderr, "Failed to initialize DHT22 GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        ret = dht22_read_data(&gpio, &temperature, &humidity);
        if (ret < 0) {
            fprintf(stderr, "Failed to read DHT22 data\n");
            break;
        }

        printf("Temperature: %d\n", temperature);
        printf("Humidity: %d\n", humidity);
        printf("------------------------------\n");

        sleep(2);
    }

    dht22_deinit_gpio(&gpio);
    gpiod_chip_close(chip);

    return 0;
}

