#define I2C_BUS "/dev/i2c-1"
#define TCS34725_ADDR 0x29
#define TCS34725_COMMAND 0x80
#define TCS34725_CLEAR 0x40
#define TCS34725_WAIT 0x10
#define TCS34725_ALS 0x23
#define TCS34725_PULSE 0x14
#define TCS34725_PULSE_100KHZ 0x03
#define TCS34725_PULSE_400KHZ 0x02
#define TCS34725_PULSE_10KHZ 0x01
#define TCS34725_PULSE_1KHZ 0x00

typedef struct {
    int fd;
    int running;
} i2c_context;

void cleanup(i2c_context *ctx) {
    if (ctx->fd >= 0) {
        close(ctx->fd);
    }
    ctx->running = 0;
}

void signal_handler(int signal) {
    cleanup(NULL);
    exit(EXIT_FAILURE);
}

int i2c_init(i2c_context *ctx) {
    ctx->fd = open(I2C_BUS, O_RDWR);
    if (ctx->fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(ctx->fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(ctx->fd);
        return -1;
    }

    // Configure TCS34725
    uint8_t config = TCS34725_CLEAR | TCS34725_WAIT | TCS34725_PULSE_100KHZ;
    if (write(ctx->fd, &config, 1) != 1) {
        fprintf(stderr, "Failed to write configuration: %s\n", strerror(errno));
        close(ctx->fd);
        return -1;
    }

    return 0;
}

void read_tcs34725(i2c_context *ctx) {
    uint8_t data[2];
    if (read(ctx->fd, data, 2) != 2) {
        fprintf(stderr, "Failed to read from TCS34725: %s\n", strerror(errno));
        return;
    }

    uint16_t red = (data[1] << 8) | data[0];
    printf("Red: %u\n", red);
}

int main() {
    i2c_context ctx = { .fd = -1, .running = 1 };
    struct sigaction sa;

    // Set up signal handler
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (i2c_init(&ctx) < 0) {
        fprintf(stderr, "TCS34725 device not found or not accessible.\n");
        return EXIT_FAILURE;
    }

    while (ctx.running) {
        read_tcs34725(&ctx);
        usleep(200000); // 0.2 seconds
    }

    cleanup(&ctx);
    return EXIT_SUCCESS;
}

