            printf("Echo did not end, sensor not responding.\n");
            gpiod_line_set_value(led_line, 1); // Blink LED to indicate error
            usleep(100000); // 100ms
            gpiod_line_set_value(led_line, 0);
            usleep(100000); // 100ms
            continue;
        }

        duration = pulse_end - pulse_start;
        distance_cm = (double)duration * 0.0343 / 2;

        // Report the distance
        snprintf(buffer, sizeof(buffer), "Distance: %.2f cm\n", distance_cm);
        printf("%s", buffer);

        // Blink LED to indicate successful measurement
        gpiod_line_set_value(led_line, 1);
        usleep(100000); // 100ms
        gpiod_line_set_value(led_line, 0);
        usleep(100000); // 100ms

        // Sleep for the poll interval
        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    if (trig_line) {
        gpiod_line_release(trig_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pigpio.h>
#include <signal.h>

#define GPIO_PIN 18
#define NUM_PIXELS 10
#define UPDATE_INTERVAL 0.01

typedef struct {
    int *gpio;
    int *strip;
    int running;
} AppContext;

void cleanup(void *ctx) {
    AppContext *app = (AppContext *)ctx;
    if (app->gpio) {
        gpioWrite(*app->gpio, PI_OFF);
        gpioTerminate();
    }
    free(app->strip);
    free(app);
}

void signal_handler(int signal) {
    AppContext *app = (AppContext *)signal_get_userdata();
    app->running = 0;
}

int main() {
    AppContext *app = malloc(sizeof(AppContext));
    if (!app) {
        fprintf(stderr, "Failed to allocate memory\n");
        return 1;
    }

    app->running = 1;
    app->gpio = malloc(sizeof(int));
    if (!app->gpio) {
        fprintf(stderr, "Failed to allocate memory for GPIO\n");
        free(app);
        return 1;
    }

    *app->gpio = GPIO_PIN;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        free(app->gpio);
        free(app);
        return 1;
    }

    if (gpioSetMode(*app->gpio, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        free(app->gpio);
        free(app);
        return 1;
    }

    app->strip = malloc(NUM_PIXELS * sizeof(int));
    if (!app->strip) {
        fprintf(stderr, "Failed to allocate memory for strip\n");
        gpioTerminate();
        free(app->gpio);
        free(app);
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    signal_set_userdata(signal_handler, app);

    while (app->running) {
        for (int i = 0; i < NUM_PIXELS; i++) {
            app->strip[i] = (i * 255) / (NUM_PIXELS - 1);
        }

        for (int i = 0; i < NUM_PIXELS; i++) {
            gpioWrite(*app->gpio, app->strip[i] ? PI_ON : PI_OFF);
            usleep(1000 * UPDATE_INTERVAL);
        }

        usleep(1000 * UPDATE_INTERVAL);
    }

    cleanup(app);
    return 0;
}

