#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define FORMAT V4L2_PIX_FMT_YUYV
#define BUFFER_COUNT 4
#define FRAME_SIZE (WIDTH * HEIGHT * 2)

typedef struct {
    int fd;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffer;
} VideoCapture;

void cleanup(VideoCapture *capture) {
    if (capture->fd >= 0) {
        ioctl(capture->fd, VIDIOC_QBUF, &capture->buf);
        close(capture->fd);
    }
    free(capture->buffer);
    free(capture);
}

void handle_signal(int sig) {
    printf("Interrupt received, cleaning up...\n");
    exit(EXIT_FAILURE);
}

int init_camera(VideoCapture *capture) {
    capture->fd = open(DEVICE, O_RDWR | O_NONBLOCK, 0);
    if (capture->fd < 0) {
        perror("Failed to open video device");
        return -1;
    }

    memset(&capture->fmt, 0, sizeof(capture->fmt));
    capture->fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    capture->fmt.fmt.pix.width = WIDTH;
    capture->fmt.fmt.pix.height = HEIGHT;
    capture->fmt.fmt.pix.pixelformat = FORMAT;
    capture->fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(capture->fd, VIDIOC_S_FMT, &capture->fmt) < 0) {
        perror("Failed to set format");
        close(capture->fd);
        return -1;
    }

    memset(&capture->req, 0, sizeof(capture->req));
    capture->req.count = BUFFER_COUNT;
    capture->req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    capture->req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(capture->fd, VIDIOC_REQBUFS, &capture->req) < 0) {
        perror("Failed to request buffers");
        close(capture->fd);
        return -1;
    }

    capture->buffer = malloc(FRAME_SIZE);
    if (!capture->buffer) {
        perror("Failed to allocate buffer");
        close(capture->fd);
        return -1;
    }

    capture->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    capture->buf.memory = V4L2_MEMORY_MMAP;
    capture->buf.index = 0;

    if (ioctl(capture->fd, VIDIOC_QUERYBUF, &capture->buf) < 0) {
        perror("Failed to query buffer");
        close(capture->fd);
        return -1;
    }

    if (ioctl(capture->fd, VIDIOC_QBUF, &capture->buf) < 0) {
        perror("Failed to queue buffer");
        close(capture->fd);
        return -1;
    }

    return 0;
}

int capture_frame(VideoCapture *capture, const char *filename) {
    struct v4l2_buffer buf;
    int type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (ioctl(capture->fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Failed to dequeue buffer");
        return -1;
    }

    if (read(capture->fd, capture->buffer, FRAME_SIZE) < 0) {
        perror("Failed to read frame");
        return -1;
    }

    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file");
        return -1;
    }

    if (fwrite(capture->buffer, 1, FRAME_SIZE, file) != FRAME_SIZE) {
        perror("Failed to write file");
        fclose(file);
        return -1;
    }

    fclose(file);

    if (ioctl(capture->fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Failed to queue buffer");
        return -1;
    }

    return 0;
}

int main() {
    VideoCapture *capture = malloc(sizeof(VideoCapture));
    if (!capture) {
        perror("Failed to allocate capture structure");
        return EXIT_FAILURE;
    }

    if (init_camera(capture) < 0) {
        fprintf(stderr, "Camera device not found or initialization failed.\n");
        cleanup(capture);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    char filename[256];
    time_t t;
    struct tm *tm_info;

    while (1) {
        time(&t);
        tm_info = localtime(&t);
        strftime(filename, sizeof(filename), "image_%Y%m%d_%H%M%S.h264", tm_info);

        if (capture_frame(capture, filename) < 0) {
            fprintf(stderr, "Failed to capture frame.\n");
            cleanup(capture);
            return EXIT_FAILURE;
        }

        printf("Captured image: %s\n", filename);

        usleep(50000); // 0.05 seconds
    }

    cleanup(capture);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
