#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define BME280_I2C_ADDR 0x76
#define BME280_REGISTER_CTRL_HUM 0xF2
#define BME280_REGISTER_CTRL_MEAS 0xF4
#define BME280_REGISTER_CONFIG 0xF5
#define BME280_REGISTER_PRESSURE_MSB 0xF7
#define BME280_REGISTER_PRESSURE_CSB 0xF8
#define BME280_REGISTER_PRESSURE_LSB 0xF9
#define BME280_REGISTER_TEMP_MSB 0xFA
#define BME280_REGISTER_TEMP_LSB 0xFB
#define BME280_REGISTER_HUM_MSB 0xFC
#define BME280_REGISTER_HUM_LSB 0xFD

typedef struct {
    int fd;
    int running;
} bme280_context;

void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nReceived signal, exiting...\n");
        exit(EXIT_FAILURE);
    }
}

void bme280_init(bme280_context *ctx) {
    ctx->fd = -1;
    ctx->running = 1;
}

int bme280_open(bme280_context *ctx) {
    ctx->fd = open(I2C_BUS, O_RDWR);
    if (ctx->fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(ctx->fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(ctx->fd);
        return -1;
    }

    // Set up BME280 for normal mode, 8x oversampling for pressure, 1x for temperature, 1x for humidity
    uint8_t ctrl_meas = 0x2700; // 0x27 for 8x oversampling pressure, 0x00 for 1x oversampling temp
    if (write(ctx->fd, &ctrl_meas, 1) != 1) {
        perror("Failed to write to CTRL_MEAS");
        close(ctx->fd);
        return -1;
    }

    // Set up configuration register
    uint8_t config = 0x0100; // 0x01 for filter coefficient 1, 0x00 for no standby
    if (write(ctx->fd, &config, 1) != 1) {
        perror("Failed to write to CONFIG");
        close(ctx->fd);
        return -1;
    }

    return 0;
}

void bme280_read_data(bme280_context *ctx, int *pressure, int *temperature, int *humidity) {
    // Read pressure
    uint8_t pressure_data[3];
    if (read(ctx->fd, pressure_data, 3) != 3) {
        perror("Failed to read pressure data");
        return;
    }

    // Read temperature
    uint8_t temp_data[2];
    if (read(ctx->fd, temp_data, 2) != 2) {
        perror("Failed to read temperature data");
        return;
    }

    // Read humidity
    uint8_t hum_data[2];
    if (read(ctx->fd, hum_data, 2) != 2) {
        perror("Failed to read humidity data");
        return;
    }

    // Convert pressure
    *pressure = (pressure_data[0] << 12) | (pressure_data[1] << 4) | (pressure_data[2] >> 4);

    // Convert temperature
    *temperature = (temp_data[0] << 8) | temp_data[1];

    // Convert humidity
    *humidity = (hum_data[0] << 8) | hum_data[1];
}

void bme280_close(bme280_context *ctx) {
    if (ctx->fd >= 0) {
        close(ctx->fd);
    }
}

int main() {
    bme280_context ctx;
    bme280_init(&ctx);

    if (bme280_open(&ctx) < 0) {
        fprintf(stderr, "BME280 device not found or not accessible. Exiting.\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (ctx.running) {
        int pressure, temperature, humidity;
        bme280_read_data(&ctx, &pressure, &temperature, &humidity);

        // Convert to actual values (simplified)
        // These are simplified conversions and may not be accurate for all use cases
        double pressure_pa = (double)pressure / 256.0;
        double temperature_c = (double)temperature / 16384.0 * 50.0 - 64.0;
        double humidity_rh = (double)humidity / 16384.0 * 100.0;

        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strcspn(timestamp, "\n")] = '\0'; // Remove newline

        printf("%s - Pressure: %.2f Pa, Temperature: %.2f °C, Humidity: %.2f %%\n",
               timestamp, pressure_pa, temperature_c, humidity_rh);

        sleep(5);
    }

    bme280_close(&ctx);
    return EXIT_SUCCESS;
}

