int i2c_write(int file_desc, uint8_t device_addr, uint8_t reg_addr, uint8_t data) {
    uint8_t buffer[2];
    buffer[0] = reg_addr;
    buffer[1] = data;
    if (ioctl(file_desc, I2C_SLAVE, device_addr) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }
    if (write(file_desc, buffer, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int i2c_read(int file_desc, uint8_t device_addr, uint8_t reg_addr, uint8_t *buffer, size_t len) {
    if (ioctl(file_desc, I2C_SLAVE, device_addr) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }
    buffer[0] = reg_addr;
    if (write(file_desc, buffer, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(file_desc, buffer, len) != len) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

