    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get ECHO line\n");
        goto error_close_line;
    }

    ret = gpiod_line_request_input(echo_line, "echo");
    if (ret < 0) {
        fprintf(stderr, "Failed to request ECHO line as input: %s\n", strerror(errno));
        goto error_close_line;
    }

    // Configure GND pin (output, but used as ground, so set to low)
    gnd_line = gpiod_chip_get_line(chip, GND_PIN);
    if (!gnd_line) {
        fprintf(stderr, "Failed to get GND line\n");
        goto error_close_line;
    }

    ret = gpiod_line_request_output(gnd_line, "gnd", GPIO_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GND line as output: %s\n", strerror(errno));
        goto error_close_line;
    }

    // Set GND pin to low (ground)
    ret = gpiod_line_set_value(gnd_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GND line to low: %s\n", strerror(errno));
        goto error_close_line;
    }

    while (1) {
        // Send a 10us pulse to TRIG pin
        gpiod_line_set_value(trig_line, 1);
        usleep(10);
        gpiod_line_set_value(trig_line, 0);

        // Wait for ECHO pin to go high
        pulse_start = 0;
        while (gpiod_line_get_value(echo_line) == 0) {
            if (pulse_start == 0) {
                pulse_start = gpiod_line_get_value(echo_line);
            }
            if (pulse_start == 0) {
                usleep(1);
            } else {
                break;
            }
        }

        if (pulse_start == 0) {
            fprintf(stderr, "ECHO pin did not go high, no signal detected\n");
            usleep(100000); // Wait 100ms before next attempt
            continue;
        }

        // Wait for ECHO pin to go low
        while (gpiod_line_get_value(echo_line) == 1) {
            pulse_end = gpiod_line_get_value(echo_line);
            if (pulse_end == 1) {
                usleep(1);
            } else {
                break;
            }
        }

        if (pulse_end == 0) {
            fprintf(stderr, "ECHO pin did not go low, no signal detected\n");
            usleep(100000); // Wait 100ms before next attempt
            continue;
        }

        pulse_duration = (pulse_end - pulse_start) * 1000000; // in microseconds

        if (pulse_duration < MIN_PULSE_WIDTH_US || pulse_duration > MAX_PULSE_WIDTH_US) {
            fprintf(stderr, "Invalid pulse duration: %u us\n", pulse_duration);
            usleep(100000); // Wait 100ms before next attempt
            continue;
        }

        // Calculate distance in cm
        distance_cm = (double) pulse_duration * 0.0343 / 2;

        if (distance_cm < 0 || distance_cm > MAX_DISTANCE_CM) {
            fprintf(stderr, "Invalid distance: %.2f cm\n", distance_cm);
            usleep(100000); // Wait 100ms before next attempt
            continue;
        }

        // Output the valid distance
        printf("Distance: %.2f cm\n", distance_cm);

        // Wait 100ms before next measurement
        usleep(100000);
    }

    // Clean up
    gpiod_line_set_value(trig_line, 0);
    gpiod_line_set_value(echo_line, 0);
    gpiod_line_set_value(gnd_line, 0);

    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_line_release(gnd_line);

    gpiod_chip_close(chip);

    return 0;

error_close_line:
    if (trig_line) gpiod_line_release(trig_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (gnd_line) gpiod_line_release(gnd_line);
    if (chip) gpiod_chip_close(chip);
    return 1;

error_close_chip:
    if (chip) gpiod_chip_close(chip);
    return 1;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define GPIO_LINE_NAME "gpio17"
#define INTERVAL_MS 1000

static int running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_line *line = NULL;
    struct gpiod_chip *chip = NULL;
    int ret;

    // Set up signal handler for clean exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, GPIO_LINE_NAME, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_PIN, strerror(-ret));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        // Toggle the GPIO state
        int current_value = gpiod_line_get_value(line);
        int new_value = (current_value == 0) ? 1 : 0;

        ret = gpiod_line_set_value(line, new_value);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO line %d: %s\n", GPIO_PIN, strerror(-ret));
            break;
        }

        // Report the state to stdout
        printf("GPIO %d: %d\n", GPIO_PIN, new_value);
        fflush(stdout);

        // Wait for the next interval
        usleep(INTERVAL_MS * 1000);
    }

    // Clean up resources
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

