#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <gpiod.h>
#include <signal.h>

#define GPIO_PIN_2 2
#define GPIO_PIN_3 3
#define GPIO_PIN_23 23

struct gpiod_line *lines[3];
int line_count = 3;
int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void cleanup() {
    for (int i = 0; i < line_count; i++) {
        gpiod_line_release(lines[i]);
    }
    printf("Cleanup complete.\n");
    exit(EXIT_SUCCESS);
}

int main() {
    struct gpiod_chip *chip;
    int ret;

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    // Initialize each GPIO line
    for (int i = 0; i < line_count; i++) {
        int pin = (i == 0) ? GPIO_PIN_2 :
                  (i == 1) ? GPIO_PIN_3 :
                  GPIO_PIN_23;

        lines[i] = gpiod_chip_get_line(chip, pin);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for GPIO %d\n", pin);
            cleanup();
            exit(EXIT_FAILURE);
        }

        ret = gpiod_line_request_output(lines[i], "gpio-output", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %d as output: %s\n", pin, strerror(errno));
            cleanup();
            exit(EXIT_FAILURE);
        }
    }

    while (running) {
        for (int i = 0; i < line_count; i++) {
            int pin = (i == 0) ? GPIO_PIN_2 :
                      (i == 1) ? GPIO_PIN_3 :
                      GPIO_PIN_23;

            int value = (i % 2 == 0) ? 1 : 0; // Alternate between 1 and 0
            ret = gpiod_line_set_value(lines[i], value);
            if (ret < 0) {
                fprintf(stderr, "Failed to set value for GPIO %d: %s\n", pin, strerror(errno));
                cleanup();
                exit(EXIT_FAILURE);
            }

            printf("GPIO %d set to %d\n", pin, value);
        }

        sleep(2);
    }

    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pthread.h>
#include <mosquitto.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MAX_SPEED_HZ 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define MQTT_BROKER "mqtt.broker.address"
#define MQTT_TOPIC "sensor/readings"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "sensor_client"

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int init_spi() {
    int fd = open(SPI_DEVICE, O_RDWR | O_SYNC);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_MAX_SPEED_HZ) < 0) {
        perror("Failed to set SPI max speed");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(fd);
        return -1;
    }

    return fd;
}

void read_sensor(int spi_fd) {
    struct spi_ioc_transfer spi = {
        .tx_buf = (unsigned long)NULL,
        .rx_buf = (unsigned long)NULL,
        .len = 1,
        .delay_usecs = 0,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    uint8_t tx[1] = {0x01};
    uint8_t rx[1];

    spi.tx_buf = (unsigned long)tx;
    spi.rx_buf = (unsigned long)rx;
    spi.len = 1;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("SPI transfer failed");
        exit(EXIT_FAILURE);
    }

    printf("Sensor reading: 0x%02X\n", rx[0]);
}

void mqtt_publish(const char *topic, const char *payload) {
    struct mosquitto *mosq = NULL;
    int rc;

    rc = mosquitto_lib_init();
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Failed to initialize MQTT library\n");
        exit(EXIT_FAILURE);
    }

    rc = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (rc == NULL) {
        fprintf(stderr, "Failed to create MQTT client\n");
        mosquitto_lib_cleanup();
        exit(EXIT_FAILURE);
    }

    rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        exit(EXIT_FAILURE);
    }

    rc = mosquitto_publish(mosq, NULL, topic, strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Failed to publish MQTT message\n");
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        exit(EXIT_FAILURE);
    }

    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
}

int main() {
    int spi_fd = -1;
    struct sigaction sa;

    // Set up signal handler
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set up signal handler");
        exit(EXIT_FAILURE);
    }

    // Initialize SPI
    spi_fd = init_spi();
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        exit(EXIT_FAILURE);
    }

    // Read sensor and publish
    read_sensor(spi_fd);
    char payload[16];
    snprintf(payload, sizeof(payload), "%02X", 0x01); // Example payload
    mqtt_publish(MQTT_TOPIC, payload);

    // Clean up
    close(spi_fd);
    exit(EXIT_SUCCESS);
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define INTERVAL 5000  // 5 seconds in milliseconds

int main() {
    int gpio = GPIO_PIN;
    int pwm_value = 0;
    int result;

    // Initialize pigpio
    if ((result = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", gpioGetErrorString(result));
        return EXIT_FAILURE;
    }

    // Check if the GPIO is available
    if (!gpioIsPwmAvailable(gpio)) {
        fprintf(stderr, "GPIO %d is not available for PWM.\n", gpio);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up PWM on the GPIO
    if ((result = gpioPWM(gpio, pwm_value)) != 0) {
        fprintf(stderr, "Failed to set PWM on GPIO %d: %s\n", gpio, gpioGetErrorString(result));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Report initial state
    printf("PWM started on GPIO %d with value %d\n", gpio, pwm_value);

    // Main loop
    while (1) {
        // Toggle PWM value
        pwm_value = (pwm_value == 0) ? 1000 : 0;

        // Set new PWM value
        if ((result = gpioPWM(gpio, pwm_value)) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d: %s\n", gpio, gpioGetErrorString(result));
            gpioTerminate();
            return EXIT_FAILURE;
        }

        // Report new state
        printf("PWM updated on GPIO %d to value %d\n", gpio, pwm_value);

        // Wait for the interval
        usleep(INTERVAL * 1000);
    }

    // Clean up on exit
    gpioPWM(gpio, 0);  // Ensure PWM is stopped
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <libgpiod.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define MAX_WAIT_US 100000  // 100ms max wait for echo
#define POLL_INTERVAL_MS 200  // 200ms between measurements

int main() {
    struct gpiod_line *trig_line = NULL;
    struct gpiod_line *echo_line = NULL;
    struct gpiod_line_request_config trig_req = GPIOD_LINE_REQUEST_CONFIG_DEFAULTS;
    struct gpiod_line_request_config echo_req = GPIOD_LINE_REQUEST_CONFIG_DEFAULTS;
    int ret;

    // Initialize GPIO lines
    trig_req.consumer = "hc-sr04_trig";
    trig_req.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;
    trig_req.direction = GPIOD_LINE_DIRECTION_OUTPUT;

    echo_req.consumer = "hc-sr04_echo";
    echo_req.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;
    echo_req.direction = GPIOD_LINE_DIRECTION_INPUT;

    // Open GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open(-1);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request TRIG pin
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        fprintf(stderr, "Failed to get TRIG line %d\n", TRIG_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_config(trig_line, &trig_req);
    if (ret < 0) {
        fprintf(stderr, "Failed to request TRIG line: %s\n", strerror(errno));
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request ECHO pin
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get ECHO line %d\n", ECHO_PIN);
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_config(echo_line, &echo_req);
    if (ret < 0) {
        fprintf(stderr, "Failed to request ECHO line: %s\n", strerror(errno));
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Trigger pulse
        gpiod_line_set_value(trig_line, 1);
        usleep(10);  // 10us pulse
        gpiod_line_set_value(trig_line, 0);

        // Wait for echo start
        int echo_start = 0;
        int timeout = 0;
        while (gpiod_line_get_value(echo_line) == 0 && timeout < MAX_WAIT_US) {
            usleep(1);
            timeout++;
        }

        if (timeout >= MAX_WAIT_US) {
            fprintf(stderr, "Echo not detected, skipping measurement\n");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        // Measure echo duration
        long start_time = 0;
        long end_time = 0;
        long duration = 0;

        // Start time
        start_time = gettimeofday_us();

        // Wait for echo to end
        while (gpiod_line_get_value(echo_line) == 1 && timeout < MAX_WAIT_US) {
            usleep(1);
            timeout++;
        }

        if (timeout >= MAX_WAIT_US) {
            fprintf(stderr, "Echo timeout, skipping measurement\n");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        end_time = gettimeofday_us();
        duration = end_time - start_time;

        // Convert to distance in cm
        double distance_cm = (double)duration * 0.0343 / 2;

        // Print result
        printf("Distance: %.2f cm\n", distance_cm);

        // Sleep before next measurement
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Cleanup
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PINS 4
#define GPIO_PIN_17 17
#define GPIO_PIN_18 18
#define GPIO_PIN_22 22
#define GPIO_PIN_23 23

typedef struct {
    int pin;
    int duty_cycle;
    int gpio;
} gpio_pwm_t;

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

int main() {
    int i;
    int result;
    gpio_pwm_t pwm_pins[GPIO_PINS] = {
        {GPIO_PIN_17, 50, GPIO_PIN_17},
        {GPIO_PIN_18, 50, GPIO_PIN_18},
        {GPIO_PIN_22, 50, GPIO_PIN_22},
        {GPIO_PIN_23, 50, GPIO_PIN_23}
    };

    // Initialize pigpio
    if ((result = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", result);
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up PWM for each pin
    for (i = 0; i < GPIO_PINS; i++) {
        if (gpioSetMode(pwm_pins[i].gpio, PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set mode for GPIO %d\n", pwm_pins[i].gpio);
            gpioTerminate();
            return 1;
        }

        if (gpioSetPWMFrequency(pwm_pins[i].gpio, 1000) < 0) {
            fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", pwm_pins[i].gpio);
            gpioTerminate();
            return 1;
        }

        if (gpioPWM(pwm_pins[i].gpio, pwm_pins[i].duty_cycle) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", pwm_pins[i].gpio);
            gpioTerminate();
            return 1;
        }
    }

    while (running) {
        for (i = 0; i < GPIO_PINS; i++) {
            int current_duty = gpioGetPWMduty(pwm_pins[i].gpio);
            printf("GPIO %d: Duty Cycle = %d%%\n", pwm_pins[i].gpio, current_duty);
        }

        sleep(100); // 0.1 seconds
    }

    // Clean up
    for (i = 0; i < GPIO_PINS; i++) {
        gpioPWM(pwm_pins[i].gpio, 0);
    }

    gpioTerminate();

    return 0;
}

