    if (res != 2) {
        fprintf(stderr, "Failed to read from sensor: %d\n", res);
        return -1;
    }

    // Check for valid reading (example: non-zero value)
    if (buf[0] == 0 && buf[1] == 0) {
        fprintf(stderr, "Invalid sensor reading: 0x%02X 0x%02X\n", buf[0], buf[1]);
        return -1;
    }

    return (buf[0] << 8) | buf[1];
}

void cleanup(int fd) {
    if (fd >= 0) {
        close(fd);
    }
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
}

int main() {
    int fd;
    int result;
    int retry = 0;
    int sensor_value;
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    MQTTClient_message msg = MQTTClient_message_initializer;
    char payload[32];

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C address
    if (ioctl(fd, I2C_TEN, 0) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Try to read from sensor with retries
    while (retry < MAX_RETRIES) {
        sensor_value = read_sensor(fd);
        if (sensor_value >= 0) {
            break;
        }
        fprintf(stderr, "Sensor not responding, retrying in %d ms...\n", RETRY_DELAY);
        usleep(RETRY_DELAY * 1000);
        retry++;
    }

    if (retry >= MAX_RETRIES) {
        fprintf(stderr, "Sensor not responding after %d retries.\n", MAX_RETRIES);
        cleanup(fd);
        return 1;
    }

    // Initialize MQTT client
    MQTTClient_create(&client, MQTT_BROKER, "sensor_client", MQTTCLIENT_PERSISTENCE_NONE, NULL);

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if (MQTTClient_connect(client, &conn_opts) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", MQTTClient_getErrorStr(client));
        cleanup(fd);
        return 1;
    }

    // Prepare message
    sprintf(payload, "%d", sensor_value);
    msg.payload = payload;
    msg.payloadlen = strlen(payload);
    msg.qos = 1;
    msg.retained = 0;

    // Publish message
    if (MQTTClient_publishMessage(client, MQTT_TOPIC, &msg, NULL) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message: %s\n", MQTTClient_getErrorStr(client));
        MQTTClient_disconnect(client, 1000);
        cleanup(fd);
        return 1;
    }

    // Wait for publish to complete
    MQTTClient_waitForCompletion(client, msg.msgId, 1000);

    // Clean up
    cleanup(fd);
    return 0;
}

