#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <gpiod.h>

#define GPIO_PIN_17 17
#define GPIO_PIN_18 18
#define INTERVAL_MS 50

int main() {
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line18 = NULL;
    struct gpiod_chip *chip;
    int ret;
    int state17, state18;
    struct timespec ts = {0, INTERVAL_MS * 1000000};

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request line 17
    line17 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    if (!line17) {
        fprintf(stderr, "Failed to get line %d\n", GPIO_PIN_17);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line17, "output17", GPIO_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_PIN_17, strerror(errno));
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line 18
    line18 = gpiod_chip_get_line(chip, GPIO_PIN_18);
    if (!line18) {
        fprintf(stderr, "Failed to get line %d\n", GPIO_PIN_18);
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line18, "output18", GPIO_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_PIN_18, strerror(errno));
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Toggle state for GPIO 17
        state17 = gpiod_line_get_value(line17);
        if (state17 < 0) {
            fprintf(stderr, "Failed to get value from line %d: %s\n", GPIO_PIN_17, strerror(errno));
            break;
        }

        // Toggle state for GPIO 18
        state18 = gpiod_line_get_value(line18);
        if (state18 < 0) {
            fprintf(stderr, "Failed to get value from line %d: %s\n", GPIO_PIN_18, strerror(errno));
            break;
        }

        // Output current states
        printf("GPIO 17: %d, GPIO 18: %d\n", state17, state18);
        fflush(stdout);

        // Toggle GPIO 17
        ret = gpiod_line_set_value(line17, 1 - state17);
        if (ret < 0) {
            fprintf(stderr, "Failed to set value on line %d: %s\n", GPIO_PIN_17, strerror(errno));
            break;
        }

        // Toggle GPIO 18
        ret = gpiod_line_set_value(line18, 1 - state18);
        if (ret < 0) {
            fprintf(stderr, "Failed to set value on line %d: %s\n", GPIO_PIN_18, strerror(errno));
            break;
        }

        // Sleep for 0.05 seconds
        nanosleep(&ts, NULL);
    }

    // Cleanup
    gpiod_line_release(line17);
    gpiod_line_release(line18);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN 17
#define INTERVAL 5

static int running = 1;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        running = 0;
    }
}

int main() {
    struct gpiod_line *line = NULL;
    struct gpiod_line_request_config req_config;
    int ret;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize libgpiod
    ret = gpiod_chip_open_by_label("gpiochip0");
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_strerror(ret));
        exit(EXIT_FAILURE);
    }

    // Configure line request
    gpiod_line_request_config_init(&req_config);
    req_config.consumer = "gpio-output";
    req_config.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;
    req_config.output = 1;

    // Request the line
    line = gpiod_chip_get_line(ret, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(ret);
        exit(EXIT_FAILURE);
    }

