    req.consumer = "gpio-test";
    req.line_offset = GPIO_PIN;
    req.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;
    req.direction = GPIOD_LINE_DIRECTION_OUTPUT;

    // Open the GPIO line
