int setup_uart() {
    struct termios tty;
    int fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        perror("Failed to open UART device");
        return -1;
    }

    if (tcgetattr(fd, &tty) != 0) {
        perror("Failed to get terminal attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag &= ~PARENB;        // No parity
    tty.c_cflag &= ~CSTOPB;        // 1 stop bit
    tty.c_cflag &= ~CSIZE;         // Clear data size mask
    tty.c_cflag |= CS8;            // 8 bits per byte
    tty.c_cflag &= ~CRTSCTS;       // No hardware flow control
    tty.c_cflag |= CREAD | CLOCAL; // Enable receiver, ignore modem control lines

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG); // No canonical mode, no echo
    tty.c_oflag &= ~OPOST; // Output processing off

    tty.c_cc[VTIME] = 0;     // Wait 0 seconds for input
    tty.c_cc[VMIN] = 1;      // Read at least 1 character

    if (tcsetattr(fd, TCSAFLUSH, &tty) != 0) {
        perror("Failed to set terminal attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uart_fd = setup_uart();
    if (uart_fd < 0) {
        fprintf(stderr, "UART setup failed\n");
        exit(EXIT_FAILURE);
    }

    char buffer[BUF_SIZE];
    ssize_t bytes_read;

    while (running) {
        bytes_read = read(uart_fd, buffer, BUF_SIZE - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("Received: %s\n", buffer);
            fflush(stdout);
        }
        usleep(10000); // 10ms delay to prevent busy waiting
    }

    close_uart();
    exit(EXIT_SUCCESS);
}

