    }

    // Save original attributes
    saved_tty = tty;

    // Set raw mode
    cfmakeraw(&tty);

    // Set baud rate
    if (cfsetispeed(&tty, BAUD_RATE) != 0 || cfsetospeed(&tty, BAUD_RATE) != 0) {
        perror("Failed to set baud rate");
        cleanup(0);
    }

    // Set data bits, stop bits, parity
    tty.c_cflag &= ~CSTOPB;    // 1 stop bit
    tty.c_cflag &= ~CSIZE;     // Clear bit mask for data bits
    tty.c_cflag |= DATA_BITS;  // 8 data bits
    tty.c_cflag &= ~PARENB;    // No parity
    tty.c_cflag &= ~PARODD;    // No parity

    // Enable receiver and set local mode
    tty.c_cflag |= (CLOCAL | CREAD);

    // Set input and output modes
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG); // No canonical mode, no echo
    tty.c_oflag &= ~OPOST; // Raw output

    // Set minimum number of characters to read
    tty.c_cc[VMIN] = 1;
    tty.c_cc[VTIME] = 0;

    // Apply the configuration
    if (tcsetattr(uart_fd, TCSAFLUSH, &tty) != 0) {
        perror("Failed to set terminal attributes");
        cleanup(0);
    }
}

void read_uart() {
    char buffer[256];
    ssize_t bytes_read;

    while (1) {
        bytes_read = read(uart_fd, buffer, sizeof(buffer) - 1);
        if (bytes_read < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                // No data available, continue
                continue;
            } else {
                perror("UART read error");
                cleanup(0);
            }
        }

        buffer[bytes_read] = '\0';
        printf("%s", buffer);
        fflush(stdout);
    }
}

int main() {
    // Set up signal handling for clean exit
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    setup_uart();
    read_uart();

    return 0;
}

