#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    // Set up signal handler for graceful exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set GPIO mode to output
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    // Set PWM parameters
    if (gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(GPIO_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    // Start PWM
    if (gpioPWM(GPIO_PIN, PWM_RANGE / 2) < 0) {
        fprintf(stderr, "Failed to start PWM on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    // Report initial state
    printf("PWM started on GPIO %d (BCM), frequency: %d Hz, duty cycle: %d%%\n", GPIO_PIN, PWM_FREQUENCY, PWM_RANGE / 2);

    // Wait for signal to exit
    while (running) {
        sleep(1);
    }

    // Stop PWM
    gpioPWM(GPIO_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN 27
#define INTERVAL 2

static int running = 1;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        running = 0;
    }
}

int main() {
    struct gpiod_line *line;
    struct gpiod_line_request_config req_config;
    struct gpiod_line_settings settings;
    int ret;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize line request configuration
    gpiod_line_request_config_init(&req_config);
    req_config.consumer = "gpio_output";
    req_config.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;

    // Initialize line settings
    gpiod_line_settings_init(&settings);
    settings.direction = GPIOD_LINE_DIRECTION_OUTPUT;

    // Open the GPIO line
    line = gpiod_line_get("gpiochip4", GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        return EXIT_FAILURE;
    }

    // Request the line
    ret = gpiod_line_request_output(line, &req_config, &settings);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", gpiod_strerror(ret));
        gpiod_line_put(line);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Toggle the output state
        int current_value = gpiod_line_get_value(line);
        int new_value = (current_value == 0) ? 1 : 0;

        ret = gpiod_line_set_value(line, new_value);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO value: %s\n", gpiod_strerror(ret));
            break;
        }

        // Report the state
        printf("GPIO %d: %d\n", GPIO_PIN, new_value);
        fflush(stdout);

        // Wait for the interval
        usleep(INTERVAL * 1000000);
    }

    // Clean up
    gpiod_line_put(line);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>

#define GPIO_PWM_PINS {8, 9, 10, 11, 17}
#define NUM_PWM_PINS 5
#define PWM_FREQ 1000
#define PWM_RANGE 100

int running = 1;

void signal_handler(int signal) {
    running = 0;
}

int main() {
    int i;
    int gpio_pins[NUM_PWM_PINS] = GPIO_PWM_PINS;
    int *gpio = gpio_pins;
    int *gpio_end = gpio + NUM_PWM_PINS;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        return 1;
    }

    // Set up PWM on all GPIO pins
    for (i = 0; i < NUM_PWM_PINS; i++) {
        if (gpioSetMode(gpio[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set mode for GPIO %d: %s\n", gpio[i], strerror(errno));
            gpioTerminate();
            return 1;
        }

        if (gpioPWM(gpio[i], 0, PWM_RANGE) < 0) {
            fprintf(stderr, "Failed to set PWM for GPIO %d: %s\n", gpio[i], strerror(errno));
            gpioTerminate();
            return 1;
        }
    }

    // Set up signal handler for graceful exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        for (i = 0; i < NUM_PWM_PINS; i++) {
            int duty_cycle = (i + 1) * (PWM_RANGE / NUM_PWM_PINS);
            if (gpioPWM(gpio[i], duty_cycle, PWM_RANGE) < 0) {
                fprintf(stderr, "Failed to set PWM for GPIO %d: %s\n", gpio[i], strerror(errno));
                gpioTerminate();
                return 1;
            }
            printf("GPIO %d: duty cycle %d\n", gpio[i], duty_cycle);
        }
        sleep(1);
    }

    // Clean up
    for (i = 0; i < NUM_PWM_PINS; i++) {
        gpioPWM(gpio[i], 0, PWM_RANGE);
    }

    gpioTerminate();
    return 0;
}

