#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <libgpiod.h>

#define GPIO_PIN 4
#define MAX_RETRIES 3
#define DHT22_DATA_PIN GPIO_PIN

// DHT22 signal protocol
#define DHT22_DATA_BIT 0
#define DHT22_DATA_BYTE 8
#define DHT22_DATA_LENGTH 40

// DHT22 signal timing
#define DHT22_DATA_HIGH 500
#define DHT22_DATA_LOW 500
#define DHT22_DATA_PULSE 100

// DHT22 checksum
#define DHT22_CHECKSUM 0

// DHT22 data
typedef struct {
    uint8_t humidity;
    uint8_t humidity_dec;
    uint8_t temperature;
    uint8_t temperature_dec;
    uint8_t checksum;
} dht22_data_t;

// Function to wait for a signal
static int wait_for_signal(int fd, int pin, int expected_level) {
    int level;
    int timeout = 0;
    while (1) {
        level = gpiod_line_get_value(fd, pin);
        if (level == expected_level) {
            return 0;
        }
        if (timeout++ > 100000) {
            return -1;
        }
        usleep(1);
    }
}

// Function to read DHT22 data
static int read_dht22(int fd, int pin, dht22_data_t *data) {
    int i;
    int j;
    int data_bit;
    int data_byte;
    int data_length;
    int data_value;
    int data_checksum;
    int data_valid;

    // Set pin as output
    gpiod_line_set_value(fd, pin, 0);
    usleep(1000);

    // Send start signal
    gpiod_line_set_value(fd, pin, 1);
    usleep(1000);
    gpiod_line_set_value(fd, pin, 0);
    usleep(20000);

    // Wait for response
    if (wait_for_signal(fd, pin, 1) < 0) {
        return -1;
    }

    // Read data
    data_value = 0;
    data_checksum = 0;
    data_valid = 1;
    for (i = 0; i < DHT22_DATA_LENGTH; i++) {
        if (wait_for_signal(fd, pin, 0) < 0) {
            data_valid = 0;
            break;
        }
        usleep(DHT22_DATA_PULSE);
        if (wait_for_signal(fd, pin, 1) < 0) {
            data_valid = 0;
            break;
        }
        data_bit = 1;
        if (i % 2 == 0) {
            data_value = (data_value << 1) | data_bit;
        } else {
            data_checksum = (data_checksum << 1) | data_bit;
        }
    }

    // Check checksum
    if (data_valid && (data_checksum != (data_value >> 8))) {
        data_valid = 0;
    }

    if (data_valid) {
        data->humidity = (data_value >> 8) & 0xFF;
        data->humidity_dec = (data_value >> 4) & 0x0F;
        data->temperature = (data_value >> 12) & 0xFF;
        data->temperature_dec = (data_value >> 8) & 0x0F;
        data->checksum = data_checksum;
    }

    return data_valid;
}

int main() {
    struct gpiod_line *line;
    struct gpiod_line_request_config req_config;
    struct gpiod_line_request *request;
    dht22_data_t data;
    int retry;
    int ret;

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Open the GPIO line
    line = gpiod_line_get("gpiochip4", GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_PIN);
        gpiod_exit();
        return 1;
    }

    // Configure the line as output
    memset(&req_config, 0, sizeof(req_config));
    req_config.consumer = "dht22";
    req_config.line = line;
    req_config.request_type = GPIOD_LINE_REQUEST_OUTPUT;
    req_config.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;

    request = gpiod_line_request_config(&req_config);
    if (!request) {
        fprintf(stderr, "Failed to request GPIO line %d\n", GPIO_PIN);
        gpiod_line_put(line);
        gpiod_exit();
        return 1;
    }

    // Set the line as output
    gpiod_line_set_value(line, GPIO_PIN, 0);

    // Try to read the DHT22 sensor
    for (retry = 0; retry < MAX_RETRIES; retry++) {
        ret = read_dht22(line, GPIO_PIN, &data);
        if (ret == 1) {
            break;
        }
        usleep(100000);
    }

    if (ret != 1) {
        fprintf(stderr, "Failed to read DHT22 sensor\n");
        gpiod_line_request_free(request);
        gpiod_line_put(line);
        gpiod_exit();
        return 1;
    }

    // Output the data
    printf("Humidity: %d.%d%%\n", data.humidity, data.humidity_dec);
    printf("Temperature: %d.%d°C\n", data.temperature, data.temperature_dec);

    // Release the line
    gpiod_line_request_free(request);
    gpiod_line_put(line);
    gpiod_exit();

    return 0;
}

