#define MCP3008_CH5 0x05
#define MCP3008_CH6 0x06
#define MCP3008_CH7 0x07
#define MQTT_TOPIC "sensor/readings"
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "mcp3008_publisher"

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

void close_spi(int fd) {
    if (fd >= 0) {
        close(fd);
    }
}

void close_mosquitto(struct mosquitto *mosq) {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
}

void publish_sensor_data(struct mosquitto *mosq, int spi_fd) {
    unsigned char tx[3];
    unsigned char rx[3];
    int ret;

    tx[0] = 1 << 7 | MCP3008_ADDR | MCP3008_CH0; // Start bit, single-ended, channel 0
    tx[1] = 0;
    tx[2] = 0;

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(3), &tx);
    if (ret < 0) {
        perror("SPI read failed");
        return;
    }

    int value = (rx[1] << 8) | rx[2];
    double voltage = (double)value / 1023.0 * 3.3;

    char payload[32];
    snprintf(payload, sizeof(payload), "%.2f", voltage);

    mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    printf("Published: %.2f V\n", voltage);
}

int main() {
    int spi_fd = -1;
    struct mosquitto *mosq = NULL;
    struct mosquitto_message *msg = NULL;
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set SPI mode
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("SPI mode set failed");
        close_spi(spi_fd);
        return 1;
    }

    // Set SPI bits per word
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("SPI bits per word set failed");
        close_spi(spi_fd);
        return 1;
    }

    // Set SPI max speed
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_MAX_SPEED_HZ) < 0) {
        perror("SPI max speed set failed");
        close_spi(spi_fd);
        return 1;
    }

    // Initialize MQTT
    ret = mosquitto_lib_init();
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "MQTT library initialization failed\n");
        close_spi(spi_fd);
        return 1;
    }

    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Failed to create MQTT client\n");
        mosquitto_lib_cleanup();
        close_spi(spi_fd);
        return 1;
    }

    ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "MQTT connect failed\n");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        close_spi(spi_fd);
        return 1;
    }

    // Main loop
    while (running) {
        publish_sensor_data(mosq, spi_fd);
        sleep(1);
    }

    // Cleanup
    close_mosquitto(mosq);
    mosquitto_lib_cleanup();
    close_spi(spi_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <string.h>

#define DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define FORMAT V4L2_PIX_FMT_YUYV

int main() {
    int fd;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffer;
    ssize_t bytes_read;

    // Open the video device
    fd = open(DEVICE, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Failed to open video device");
        return 1;
    }

    // Set video format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set video format");
        close(fd);
        return 1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request buffers");
        close(fd);
        return 1;
    }

    // Query buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Failed to query buffer");
        close(fd);
        return 1;
    }

    // Map buffer
    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("Failed to map buffer");
        close(fd);
        return 1;
    }

    // Queue buffer
    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Failed to queue buffer");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Failed to start streaming");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    // Capture one frame
    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Failed to dequeue buffer");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    // Save the captured image to a file
    FILE *file = fopen("capture.yuyv", "wb");
    if (!file) {
        perror("Failed to open output file");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    bytes_read = write(file, buffer, buf.bytesused);
    if (bytes_read < 0) {
        perror("Failed to write image data");
        fclose(file);
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    fclose(file);

    // Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Failed to stop streaming");
    }

    // Unmap buffer and close device
    munmap(buffer, buf.length);
    close(fd);

    printf("Image captured and saved to 'capture.yuyv'\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>

#define GPIO_PINS 9
int pin_list[GPIO_PINS] = {4, 5, 6, 7, 8, 9};
int pwm_values[GPIO_PINS] = {128, 192, 64, 255, 128, 128}; // Example values between 0 and 255
int running = 1;

void signal_handler(int signal) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    // Set up signal handler for graceful exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    for (int i = 0; i < GPIO_PINS; i++) {
        if (gpioSetMode(pin_list[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set mode for GPIO %d\n", pin_list[i]);
            gpioTerminate();
            return 1;
        }

        if (gpioSetPWMFrequency(pin_list[i], 1000) < 0) {
            fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", pin_list[i]);
            gpioTerminate();
            return 1;
        }

        if (gpioPWM(pin_list[i], pwm_values[i]) < 0) {
            fprintf(stderr, "Failed to set PWM value for GPIO %d\n", pin_list[i]);
            gpioTerminate();
            return 1;
        }

        printf("PWM set to %d on GPIO %d\n", pwm_values[i], pin_list[i]);
    }

    // Wait for signal to exit
    while (running) {
        sleep(1);
    }

    // Clean up
    for (int i = 0; i < GPIO_PINS; i++) {
        gpioPWM(pin_list[i], 0);
    }

    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <libgpiod.h>
#include <unistd.h>
#include <signal.h>

#define GPIO_PIN_17 17
#define GPIO_PIN_18 18
#define CYCLES 3

struct gpiod_line *line17 = NULL;
struct gpiod_line *line18 = NULL;
int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void cleanup() {
    if (line17) {
        gpiod_line_release(line17);
        line17 = NULL;
    }
    if (line18) {
        gpiod_line_release(line18);
        line18 = NULL;
    }
    printf("Cleanup complete.\n");
}

int main() {
    struct gpiod_chip *chip;
    int ret;

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    // Configure GPIO 17 as output
    line17 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    if (!line17) {
        fprintf(stderr, "Failed to get line 17\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line17, "gpio17-out", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line 17 as output: %s\n", gpiod_strerror(ret));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Configure GPIO 18 as output
    line18 = gpiod_chip_get_line(chip, GPIO_PIN_18);
    if (!line18) {
        fprintf(stderr, "Failed to get line 18\n");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line18, "gpio18-out", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line 18 as output: %s\n", gpiod_strerror(ret));
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Main loop
    for (int cycle = 0; cycle < CYCLES && running; cycle++) {
        // Set GPIO 17 high
        ret = gpiod_line_set_value(line17, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line 17 high: %s\n", gpiod_strerror(ret));
            cleanup();
            exit(EXIT_FAILURE);
        }
        printf("Cycle %d: GPIO 17 set to 1\n", cycle + 1);
        usleep(500000); // 500ms

        // Set GPIO 17 low
        ret = gpiod_line_set_value(line17, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line 17 low: %s\n", gpiod_strerror(ret));
            cleanup();
            exit(EXIT_FAILURE);
        }
        printf("Cycle %d: GPIO 17 set to 0\n", cycle + 1);
        usleep(500000); // 500ms

        // Set GPIO 18 high
        ret = gpiod_line_set_value(line18, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line 18 high: %s\n", gpiod_strerror(ret));
            cleanup();
            exit(EXIT_FAILURE);
        }
        printf("Cycle %d: GPIO 18 set to 1\n", cycle + 1);
        usleep(500000); // 500ms

        // Set GPIO 18 low
        ret = gpiod_line_set_value(line18, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line 18 low: %s\n", gpiod_strerror(ret));
            cleanup();
            exit(EXIT_FAILURE);
        }
        printf("Cycle %d: GPIO 18 set to 0\n", cycle + 1);
        usleep(500000); // 500ms
    }

    // Cleanup
    cleanup();
    gpiod_chip_close(chip);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define INTERVAL 5

int main() {
    struct gpiod_line *line;
    struct gpiod_line_request_config req;
    int ret;

    // Initialize line request configuration
    gpiod_line_request_config_init(&req);
    req.consumer = "gpio-test";
    req.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;
    req.output = 1;

    // Open the GPIO line
    line = gpiod_line_get("gpiochip0", GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_PIN);
        return EXIT_FAILURE;
    }

    // Request the line
    ret = gpiod_line_request_output(line, &req);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Toggle the output state
        ret = gpiod_line_set_value(line, 1 - gpiod_line_get_value(line));
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
            gpiod_line_release(line);
            return EXIT_FAILURE;
        }

        // Report the state
        int value = gpiod_line_get_value(line);
        printf("GPIO %d state: %d\n", GPIO_PIN, value);

        // Sleep for 5 seconds
        usleep(INTERVAL * 1000000);
    }

    // Clean up on exit
    gpiod_line_release(line);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define PCF8574_ADDR 0x27
#define DISPLAY_DELAY 500000  // 0.5 seconds in microseconds

// Function to safely open I2C device
int open_i2c_device(const char *device_path) {
    int file_desc = open(device_path, O_RDWR);
    if (file_desc < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
    return file_desc;
}

// Function to safely set I2C slave address
int set_i2c_slave(int file_desc, int addr) {
    if (ioctl(file_desc, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        close(file_desc);
        exit(EXIT_FAILURE);
    }
    return 0;
}

// Function to safely write to I2C device
int write_i2c_data(int file_desc, unsigned char data) {
    if (write(file_desc, &data, 1) != 1) {
        perror("Failed to write to I2C device");
        close(file_desc);
        exit(EXIT_FAILURE);
    }
    return 0;
}

// Function to safely read from I2C device
int read_i2c_data(int file_desc, unsigned char *data) {
    if (read(file_desc, data, 1) != 1) {
        perror("Failed to read from I2C device");
        close(file_desc);
        exit(EXIT_FAILURE);
    }
    return 0;
}

// Function to safely close I2C device
void close_i2c_device(int file_desc) {
    close(file_desc);
}

// Function to safely handle signals
void handle_signal(int signal) {
    printf("\nReceived signal %d, exiting...\n", signal);
    exit(EXIT_SUCCESS);
}

// Function to display a value on the PCF8574
void display_value(int file_desc, unsigned char value) {
    if (write_i2c_data(file_desc, value) != 0) {
        fprintf(stderr, "Error writing to display\n");
    }
}

int main() {
    int i2c_file = -1;
    unsigned char display_value = 0x00;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C device
    i2c_file = open_i2c_device(I2C_BUS);

    // Set I2C slave address
    if (set_i2c_slave(i2c_file, PCF8574_ADDR) != 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        close_i2c_device(i2c_file);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Generate a value within the documented range (0x00 to 0xFF)
        display_value = (unsigned char)(rand() % 256);

        // Display the value
        display_value(i2c_file, display_value);

        // Delay for 0.5 seconds
        usleep(DISPLAY_DELAY);
    }

    // Clean up on exit
    close_i2c_device(i2c_file);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <libgpiod.h>
#include <unistd.h>
#include <signal.h>

#define GPIO_PIN 17
#define GPIO_LINE "gpio17"

struct gpiod_line *line = NULL;
int exit_flag = 0;

void handle_signal(int sig) {
    exit_flag = 1;
}

int main() {
    struct gpiod_chip *chip;
    int ret;

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the line for output
    ret = gpiod_line_request_output(line, "gpio_output", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d for output: %s\n", GPIO_PIN, gpiod_strerror(ret));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set the output to high
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO line %d to high: %s\n", GPIO_PIN, gpiod_strerror(ret));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Report the state
    printf("GPIO %d set to high\n", GPIO_PIN);

    // Wait for signal to exit
    while (!exit_flag) {
        usleep(100000); // 100ms
    }

    // Release the line and close the chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN 4
#define INTERVAL 2

static int running = 1;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        running = 0;
    }
}

int main() {
    struct gpiod_line *line = NULL;
    struct gpiod_line_request_config req_config;
    int ret;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize libgpiod
    ret = gpiod_chip_open_by_label("gpiochip4");
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_strerror(ret));
        exit(EXIT_FAILURE);
    }

    // Configure line request
    gpiod_line_request_config_init(&req_config);
    req_config.consumer = "gpio-output";
    req_config.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;
    req_config.output = 1;

    // Request the line
    line = gpiod_chip_get_line_by_offset(0); // GPIO 4 is offset 4 on gpiochip4
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line, &req_config);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", gpiod_strerror(ret));
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (running) {
        // Toggle the output
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO value: %s\n", gpiod_strerror(ret));
            break;
        }
        printf("GPIO %d set to 1\n", GPIO_PIN);
        fflush(stdout);

        sleep(INTERVAL);

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO value: %s\n", gpiod_strerror(ret));
            break;
        }
        printf("GPIO %d set to 0\n", GPIO_PIN);
        fflush(stdout);

        sleep(INTERVAL);
    }

    // Clean up
    if (line) {
        gpiod_line_release(line);
    }

    exit(EXIT_SUCCESS);
}

#include <stdio.h>
#include <stdlib.h>
#include <libgpiod.h>
#include <unistd.h>
#include <signal.h>

#define GPIO_PINS 6
#define GPIO_PIN_LIST {4, 17, 22, 23, 24, 27}

typedef struct {
    struct gpiod_line *lines[GPIO_PINS];
    int states[GPIO_PINS];
} gpio_context;

void handle_exit(int sig) {
    gpio_context *ctx = (gpio_context *)malloc(sizeof(gpio_context));
    if (ctx == NULL) {
        fprintf(stderr, "Failed to allocate memory for GPIO context\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < GPIO_PINS; i++) {
        if (ctx->lines[i]) {
            gpiod_line_release(ctx->lines[i]);
            ctx->lines[i] = NULL;
        }
    }

    free(ctx);
    exit(EXIT_SUCCESS);
}

int main() {
    gpio_context *ctx = (gpio_context *)malloc(sizeof(gpio_context));
    if (ctx == NULL) {
        fprintf(stderr, "Failed to allocate memory for GPIO context\n");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        free(ctx);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < GPIO_PINS; i++) {
        ctx->lines[i] = gpiod_chip_get_line(chip, GPIO_PIN_LIST[i]);
        if (!ctx->lines[i]) {
            fprintf(stderr, "Failed to get line for GPIO %d\n", GPIO_PIN_LIST[i]);
            free(ctx);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_request_output(ctx->lines[i], "gpio-output", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request output for GPIO %d: %s\n", GPIO_PIN_LIST[i], strerror(errno));
            free(ctx);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        ctx->states[i] = 0;
    }

    signal(SIGINT, handle_exit);
    signal(SIGTERM, handle_exit);

    for (int i = 0; i < GPIO_PINS; i++) {
        ret = gpiod_line_set_value(ctx->lines[i], 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set value for GPIO %d: %s\n", GPIO_PIN_LIST[i], strerror(errno));
            free(ctx);
            gpiod_chip_close(chip);
