#include <stdio.h>
#include <stdlib.h>
#include <libgpiod.h>
#include <unistd.h>
#include <signal.h>

#define GPIO_PIN_17 17
#define GPIO_PIN_18 18
#define GPIO_PIN_24 24

typedef struct {
    struct gpiod_line *line_17;
    struct gpiod_line *line_18;
    struct gpiod_line *line_24;
    int exit_flag;
} gpio_state;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal, exiting...\n");
        exit(EXIT_SUCCESS);
    }
}

int init_gpio_lines(gpio_state *state) {
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    state->line_17 = gpiod_line_request_output(chip, "gpio17", GPIO_PIN_17, 0);
    if (!state->line_17) {
        perror("Failed to request GPIO 17");
        gpiod_chip_close(chip);
        return -1;
    }

    state->line_18 = gpiod_line_request_output(chip, "gpio18", GPIO_PIN_18, 0);
    if (!state->line_18) {
        perror("Failed to request GPIO 18");
        gpiod_line_release(state->line_17);
        gpiod_chip_close(chip);
        return -1;
    }

    state->line_24 = gpiod_line_request_output(chip, "gpio24", GPIO_PIN_24, 0);
    if (!state->line_24) {
        perror("Failed to request GPIO 24");
        gpiod_line_release(state->line_17);
        gpiod_line_release(state->line_18);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

void set_gpio_state(gpio_state *state, int pin, int value) {
    struct gpiod_line *line = NULL;

    switch (pin) {
        case GPIO_PIN_17:
            line = state->line_17;
            break;
        case GPIO_PIN_18:
            line = state->line_18;
            break;
        case GPIO_PIN_24:
            line = state->line_24;
            break;
        default:
            fprintf(stderr, "Invalid GPIO pin\n");
            return;
    }

    if (gpiod_line_set_value(line, value) < 0) {
        perror("Failed to set GPIO value");
    } else {
        printf("Set GPIO %d to %d\n", pin, value);
    }
}

void cleanup_gpio(gpio_state *state) {
    if (state->line_17) {
        gpiod_line_release(state->line_17);
    }
    if (state->line_18) {
        gpiod_line_release(state->line_18);
    }
    if (state->line_24) {
        gpiod_line_release(state->line_24);
    }
}

int main() {
    gpio_state state = {0};
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    ret = init_gpio_lines(&state);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO lines\n");
        return EXIT_FAILURE;
    }

    set_gpio_state(&state, GPIO_PIN_17, 1);
    set_gpio_state(&state, GPIO_PIN_18, 0);
    set_gpio_state(&state, GPIO_PIN_24, 1);

    cleanup_gpio(&state);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
