#include <linux/gpio.h>
#include <libgpiod.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define MAX_WAIT_US 1000000
#define TIMEOUT_US 500000

int main() {
    struct gpiod_line *trig_line = NULL;
    struct gpiod_line *echo_line = NULL;
    struct gpiod_line_request_config trig_req = GPIOD_LINE_REQUEST_CONFIG_DEFAULTS;
    struct gpiod_line_request_config echo_req = GPIOD_LINE_REQUEST_CONFIG_DEFAULTS;
    int ret;

    // Initialize GPIO lines
    trig_req.consumer = "hc-sr04_trig";
    trig_req.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;
    trig_req.direction = GPIOD_LINE_DIRECTION_OUTPUT;

    echo_req.consumer = "hc-sr04_echo";
    echo_req.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;
    echo_req.direction = GPIOD_LINE_DIRECTION_INPUT;

    // Open GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open(-1);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request TRIG pin
    trig_line = gpiod_line_request(chip, TRIG_PIN, &trig_req);
    if (!trig_line) {
        fprintf(stderr, "Failed to request TRIG pin %d\n", TRIG_PIN);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request ECHO pin
    echo_line = gpiod_line_request(chip, ECHO_PIN, &echo_req);
    if (!echo_line) {
        fprintf(stderr, "Failed to request ECHO pin %d\n", ECHO_PIN);
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Trigger the sensor
        gpiod_line_set_value(trig_line, 1);
        usleep(10); // 10 microseconds
        gpiod_line_set_value(trig_line, 0);

        // Wait for echo to go high
        int echo_high = 0;
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);

        while (gpiod_line_get_value(echo_line) == 0) {
            if (clock_gettime(CLOCK_MONOTONIC, &end) == -1) {
                fprintf(stderr, "Failed to get time\n");
                break;
            }
            if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 100 >= MAX_WAIT_US) {
                fprintf(stderr, "Echo signal not detected, timeout\n");
                break;
            }
            usleep(1);
        }

        if (gpiod_line_get_value(echo_line) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &start);
            while (gpiod_line_get_value(echo_line) == 1) {
                if (clock_gettime(CLOCK_MONOTONIC, &end) == -1) {
                    fprintf(stderr, "Failed to get time\n");
                    break;
                }
                if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 100 >= MAX_WAIT_US) {
                    fprintf(stderr, "Echo signal too long, timeout\n");
                    break;
                }
                usleep(1);
            }

            // Calculate duration
            long duration_us = ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 100);
            double distance_cm = duration_us * 0.0343 / 2;

            printf("Distance: %.2f cm\n", distance_cm);
        } else {
            printf("No echo signal detected\n");
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Cleanup
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
