#define GPIO_PWM_1 8
#define GPIO_PWM_2 9
#define GPIO_PWM_3 11
#define GPIO_PWM_4 18

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

void setup_pwm(int gpio, int frequency, int duty_cycle) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio.\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(gpio, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output.\n", gpio);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetPWMFrequency(gpio, frequency) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d.\n", gpio);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetPWMRange(gpio, 1024) < 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d.\n", gpio);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioPWM(gpio, duty_cycle) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d.\n", gpio);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void cleanup_pwm() {
    gpioTerminate();
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_pwm(GPIO_PWM_1, 1000, 512);
    setup_pwm(GPIO_PWM_2, 1000, 512);
    setup_pwm(GPIO_PWM_3, 1000, 512);
    setup_pwm(GPIO_PWM_4, 1000, 512);

    while (running) {
        printf("PWM values set: 512 (50%%) on GPIO 8, 9, 11, 18\n");
        fflush(stdout);
        sleep(1);
    }

    cleanup_pwm();
