}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define FORMAT V4L2_PIX_FMT_YUYV
#define BUFFER_COUNT 4
#define FRAME_INTERVAL 100000000ULL // 0.1 seconds in nanoseconds

typedef struct {
    void *start;
    size_t length;
} buffer;

int fd = -1;
buffer *buffers = NULL;
unsigned int n_buffers = 0;

void cleanup(int signal) {
    if (fd >= 0) {
        for (unsigned int i = 0; i < n_buffers; ++i) {
            if (buffers[i].start)
                munmap(buffers[i].start, buffers[i].length);
        }
        close(fd);
    }
    exit(EXIT_FAILURE);
}

int open_device(const char *device) {
    fd = open(device, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", device, strerror(errno));
        return -1;
    }
    return 0;
}

int init_device() {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        return -1;
    }

    n_buffers = req.count;
    buffers = calloc(n_buffers, sizeof(*buffers));
    if (!buffers) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    for (unsigned int i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.index = i;
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "Error querying buffer %u: %s\n", i, strerror(errno));
            return -1;
        }

        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i].start == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer %u: %s\n", i, strerror(errno));
            return -1;
        }

        buffers[i].length = buf.length;
    }

    for (unsigned int i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.index = i;
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error queueing buffer %u: %s\n", i, strerror(errno));
            return -1;
        }
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int capture_frame(const char *filename) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    fwrite(buffers[buf.index].start, 1, buffers[buf.index].length, file);
    fclose(file);

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error requeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (open_device(DEVICE) < 0) {
        fprintf(stderr, "Device %s not found\n", DEVICE);
        return EXIT_FAILURE;
    }

    if (init_device() < 0) {
        fprintf(stderr, "Failed to initialize device\n");
        cleanup(0);
        return EXIT_FAILURE;
    }

    char filename[256];
    time_t timestamp;
    struct tm *tm_info;

    while (1) {
        time(&timestamp);
        tm_info = localtime(&timestamp);
        strftime(filename, sizeof(filename), "image_%Y%m%d_%H%M%S.jpg", tm_info);

        if (capture_frame(filename) < 0) {
            fprintf(stderr, "Failed to capture frame\n");
            cleanup(0);
            return EXIT_FAILURE;
        }

        usleep(FRAME_INTERVAL);
    }

    return EXIT_SUCCESS;
}

