#define GPIO_PWM_24 24

int main() {
    int gpio_18, gpio_23, gpio_24;
    int pwm_18, pwm_23, pwm_24;
    int duty_cycle = 50; // 50% duty cycle
    int period = 1000000; // 1 second period (1000000 microseconds)

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up GPIOs as PWM outputs
    gpio_18 = gpioPWM(GPIO_PWM_18, 0);
    gpio_23 = gpioPWM(GPIO_PWM_23, 0);
    gpio_24 = gpioPWM(GPIO_PWM_24, 0);

    if (gpio_18 < 0 || gpio_23 < 0 || gpio_24 < 0) {
        fprintf(stderr, "Failed to set up PWM for GPIOs\n");
        gpioTerminate();
        return 1;
    }

    // Set PWM parameters
    if (gpioSetPWMOptions(GPIO_PWM_18, period, 0) < 0 ||
        gpioSetPWMOptions(GPIO_PWM_23, period, 0) < 0 ||
        gpioSetPWMOptions(GPIO_PWM_24, period, 0) < 0) {
        fprintf(stderr, "Failed to set PWM options\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Set PWM duty cycle
        if (gpioPWM(GPIO_PWM_18, duty_cycle) < 0 ||
            gpioPWM(GPIO_PWM_23, duty_cycle) < 0 ||
            gpioPWM(GPIO_PWM_24, duty_cycle) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
            gpioTerminate();
            return 1;
        }

        // Report state
        printf("PWM duty cycle set to %d%% on GPIOs 18, 23, 24\n", duty_cycle);
        fflush(stdout);

        // Sleep for 0.1 seconds
        usleep(100000);

        // Toggle duty cycle
        duty_cycle = (duty_cycle == 0) ? 100 : 0;
    }

    // Clean up on exit
    gpioPWM(GPIO_PWM_18, 0);
    gpioPWM(GPIO_PWM_23, 0);
    gpioPWM(GPIO_PWM_24, 0);
    gpioTerminate();

    return 0;
}

