    echo_req.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;
    echo_req.direction = GPIOD_LINE_DIRECTION_INPUT;

    // Request TRIG pin
    trig_line = gpiod_line_request_by_number_optional(NULL, TRIG_PIN, &trig_req, NULL);
    if (!trig_line) {
        fprintf(stderr, "Failed to request TRIG pin %d\n", TRIG_PIN);
        exit(EXIT_FAILURE);
    }

    // Request ECHO pin
    echo_line = gpiod_line_request_by_number_optional(NULL, ECHO_PIN, &echo_req, NULL);
    if (!echo_line) {
        fprintf(stderr, "Failed to request ECHO pin %d\n", ECHO_PIN);
        gpiod_line_release(trig_line);
        exit(EXIT_FAILURE);
    }

    // Set TRIG pin high for 10 microseconds
    ret = gpiod_line_set_value(trig_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set TRIG pin high: %s\n", strerror(-ret));
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        exit(EXIT_FAILURE);
    }
    usleep(10);
    ret = gpiod_line_set_value(trig_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set TRIG pin low: %s\n", strerror(-ret));
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        exit(EXIT_FAILURE);
    }

    // Wait for ECHO pin to go high
    int echo_high = 0;
    int timeout = 0;
    while (gpiod_line_get_value(echo_line) == 0 && timeout < 100000) {
        usleep(1);
        timeout++;
    }

    if (timeout >= 100000) {
        fprintf(stderr, "ECHO pin did not go high, no response from sensor\n");
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        exit(EXIT_FAILURE);
    }

    // Measure pulse width
    long start_time = 0;
    long end_time = 0;
    int pulse_width = 0;

    // Start time
    start_time = gettime();
    while (gpiod_line_get_value(echo_line) == 1 && timeout < 100000) {
        usleep(1);
        timeout++;
