        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        exit(EXIT_FAILURE);
    }

    end_time = gettime();
    pulse_width = end_time - start_time;

    // Calculate distance
    double distance_cm = (double) pulse_width * SOUND_SPEED_CM_US / 2.0;

    if (distance_cm < 0 || distance_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance_cm);
