int sht31_read_measurement(sht31_measurement_t *measurement) {
    uint8_t cmd[2] = {0x27, 0x10};
    if (write(i2c_fd, cmd, 2) != 2) {
        perror("Failed to write command");
        return -1;
    }

    usleep(100000); // Wait for measurement to complete

    uint8_t rx[6];
    if (read(i2c_fd, rx, 6) != 6) {
        perror("Failed to read measurement");
        return -1;
    }

    uint16_t raw_hum = (rx[0] << 8) | rx[1];
    uint16_t raw_temp = (rx[3] << 8) | rx[4];

    // Check for validity
    if ((rx[2] & 0x80) != 0x80 || (rx[5] & 0x80) != 0x80) {
        fprintf(stderr, "Invalid measurement data\n");
        return -1;
    }

    // Convert to humidity and temperature
    measurement->humidity = (raw_hum * 100) / 65536.0;
    measurement->temperature = (raw_temp * 175.0 / 65535.0) - 46.85;

    return 0;
}

int main() {
    if (i2c_init() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    sht31_measurement_t measurement;
    while (1) {
        if (sht31_read_measurement(&measurement) < 0) {
            fprintf(stderr, "Failed to read measurement, exiting.\n");
            cleanup(0);
        }

        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strcspn(timestamp, "\n")] = '\0';

        printf("%s - Humidity: %.2f%%, Temperature: %.2f°C\n",
               timestamp, measurement.humidity, measurement.temperature);

        sleep(5);
    }

    return EXIT_SUCCESS;
}

