#define GPIO_PINS 10
int pin_numbers[GPIO_PINS] = {5, 6, 12, 16, 19, 20, 23, 24, 25, 26};

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[GPIO_PINS];
    int i, ret;

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Initialize lines
    for (i = 0; i < GPIO_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pin_numbers[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d: %s\n", pin_numbers[i], strerror(errno));
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        // Configure each line as output
        ret = gpiod_line_request_output(lines[i], "gpio-output", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %d as output: %s\n", pin_numbers[i], strerror(errno));
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Set each line to high
    for (i = 0; i < GPIO_PINS; i++) {
        ret = gpiod_line_set_value(lines[i], 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line %d to high: %s\n", pin_numbers[i], strerror(errno));
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Report the state applied
    printf("GPIO pins %d, %d, %d, %d, %d, %d, %d, %d, %d, %d set to high.\n",
           pin_numbers[0], pin_numbers[1], pin_numbers[2], pin_numbers[3],
           pin_numbers[4], pin_numbers[5], pin_numbers[6], pin_numbers[7],
           pin_numbers[8], pin_numbers[9]);

    // Release all lines
    for (i = 0; i < GPIO_PINS; i++) {
        gpiod_line_release(lines[i]);
    }

    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <gpiod.h>
#include <signal.h>

#define GPIO_PIN_17 17
#define GPIO_PIN_22 22
#define GPIO_PIN_27 27

typedef struct {
    struct gpiod_line *line17;
    struct gpiod_line *line22;
    struct gpiod_line *line27;
} gpio_lines;

void cleanup_gpio(gpio_lines *gpio) {
    if (gpio->line17) {
        gpiod_line_release(gpio->line17);
    }
    if (gpio->line22) {
        gpiod_line_release(gpio->line22);
    }
    if (gpio->line27) {
        gpiod_line_release(gpio->line27);
    }
}

void handle_signal(int sig) {
    cleanup_gpio(NULL);
    exit(EXIT_FAILURE);
}

int main() {
    gpio_lines gpio = {0};
    struct gpiod_chip *chip;
    int ret;

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Configure GPIO 17 as output
    gpio.line17 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    if (!gpio.line17) {
        fprintf(stderr, "Failed to get GPIO 17 line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(gpio.line17, "gpio17", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO 17 as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure GPIO 22 as output
    gpio.line22 = gpiod_chip_get_line(chip, GPIO_PIN_22);
    if (!gpio.line22) {
        fprintf(stderr, "Failed to get GPIO 22 line\n");
        gpiod_line_release(gpio.line17);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(gpio.line22, "gpio22", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO 22 as output: %s\n", strerror(errno));
        gpiod_line_release(gpio.line17);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure GPIO 27 as output
    gpio.line27 = gpiod_chip_get_line(chip, GPIO_PIN_27);
    if (!gpio.line27) {
        fprintf(stderr, "Failed to get GPIO 27 line\n");
        gpiod_line_release(gpio.line17);
        gpiod_line_release(gpio.line22);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(gpio.line27, "gpio27", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO 27 as output: %s\n", strerror(errno));
        gpiod_line_release(gpio.line17);
        gpiod_line_release(gpio.line22);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Toggle GPIO 17
        int val17 = gpiod_line_get_value(gpio.line17);
        ret = gpiod_line_set_value(gpio.line17, (val17 == 0) ? 1 : 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO 17: %s\n", strerror(errno));
            cleanup_gpio(&gpio);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        printf("GPIO 17: %d\n", (val17 == 0) ? 1 : 0);

        // Toggle GPIO 22
        int val22 = gpiod_line_get_value(gpio.line22);
        ret = gpiod_line_set_value(gpio.line22, (val22 == 0) ? 1 : 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO 22: %s\n", strerror(errno));
            cleanup_gpio(&gpio);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        printf("GPIO 22: %d\n", (val22 == 0) ? 1 : 0);

        // Toggle GPIO 27
        int val27 = gpiod_line_get_value(gpio.line27);
        ret = gpiod_line_set_value(gpio.line27, (val27 == 0) ? 1 : 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO 27: %s\n", strerror(errno));
            cleanup_gpio(&gpio);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        printf("GPIO 27: %d\n", (val27 == 0) ? 1 : 0);

        sleep(1);
    }

    // This point is unreachable due to signal handling
    cleanup_gpio(&gpio);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>

#define GPIO_PINS 4
#define GPIO_PIN_17 17
#define GPIO_PIN_18 18
#define GPIO_PIN_22 22
#define GPIO_PIN_27 27

int gpio_fd[GPIO_PINS];
int pwm_enabled = 1;

void cleanup(int signal) {
    if (pwm_enabled) {
        for (int i = 0; i < GPIO_PINS; i++) {
            gpioPWM(gpio_fd[i], 0);
            gpioWrite(gpio_fd[i], PI_OFF);
        }
        gpioTerminate();
    }
    exit(EXIT_FAILURE);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Set up signal handling for clean exit
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize GPIO pins
    for (int i = 0; i < GPIO_PINS; i++) {
        int pin = (i == 0) ? GPIO_PIN_17 :
                  (i == 1) ? GPIO_PIN_18 :
                  (i == 2) ? GPIO_PIN_22 :
                  GPIO_PIN_27;

        if (gpioSetMode(pin, PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set mode for GPIO %d: %s\n", pin, strerror(errno));
            cleanup(0);
            return EXIT_FAILURE;
        }

        gpio_fd[i] = gpioGetPWMHandle(pin);
        if (gpio_fd[i] < 0) {
            fprintf(stderr, "Failed to get PWM handle for GPIO %d: %s\n", pin, strerror(errno));
            cleanup(0);
            return EXIT_FAILURE;
        }

        if (gpioPWM(gpio_fd[i], 0) < 0) {
            fprintf(stderr, "Failed to set PWM for GPIO %d: %s\n", pin, strerror(errno));
            cleanup(0);
            return EXIT_FAILURE;
        }
    }

    // Report initial state
    printf("PWM initialized on GPIO 17, 18, 22, 27 (BCM)\n");
    printf("Initial state: all outputs are off\n");

    // Wait for user input or signal
    sleep(10);

    cleanup(0);
    return EXIT_SUCCESS;
}

