    int ret;

    // Open the GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Request line 2 (BCM 2)
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        fprintf(stderr, "Failed to get line 2: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line2, "gpio2-out", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line 2 as output: %s\n", strerror(-ret));
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line 3 (BCM 3)
    line3 = gpiod_chip_get_line(chip, GPIO_PIN_3);
    if (!line3) {
        fprintf(stderr, "Failed to get line 3: %s\n", strerror(errno));
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line3, "gpio3-out", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line 3 as output: %s\n", strerror(-ret));
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Toggle GPIO 2
        int val2 = gpiod_line_get_value(line2);
        if (val2 < 0) {
            fprintf(stderr, "Failed to get value of line 2: %s\n", strerror(-val2));
            break;
        }
        ret = gpiod_line_set_value(line2, 1 - val2);
        if (ret < 0) {
            fprintf(stderr, "Failed to set value of line 2: %s\n", strerror(-ret));
            break;
        }

        // Toggle GPIO 3
        int val3 = gpiod_line_get_value(line3);
        if (val3 < 0) {
            fprintf(stderr, "Failed to get value of line 3: %s\n", strerror(-val3));
            break;
