        ret = gpiod_line_set_value(line3, 1 - val3);
        if (ret < 0) {
            fprintf(stderr, "Failed to set value of line 3: %s\n", strerror(-ret));
            break;
        }

        // Report state
        printf("GPIO 2: %d, GPIO 3: %d\n", val2, val3);
        fflush(stdout);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Cleanup
    gpiod_line_release(line2);
    gpiod_line_release(line3);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN_2 2
#define GPIO_PIN_17 17
#define INTERVAL 60

static int running = 1;

void handle_signal(int sig) {
    running = 0;
}

int main() {
    struct gpiod_line *line_2 = NULL;
    struct gpiod_line *line_17 = NULL;
    struct gpiod_chip *chip = NULL;
    int ret;

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Configure GPIO 2 (BCM 2) as output
    line_2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line_2) {
        fprintf(stderr, "Failed to get line for GPIO 2\n");
        goto error_close_chip;
    }

    ret = gpiod_line_request_output(line_2, "gpio2-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line for GPIO 2: %s\n", strerror(errno));
        goto error_free_line_2;
    }

    // Configure GPIO 17 (BCM 17) as output
    line_17 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    if (!line_17) {
        fprintf(stderr, "Failed to get line for GPIO 17\n");
        goto error_free_line_2;
    }

    ret = gpiod_line_request_output(line_17, "gpio17-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line for GPIO 17: %s\n", strerror(errno));
        goto error_free_line_17;
    }

    // Main loop
    while (running) {
        // Toggle GPIO 2
        ret = gpiod_line_set_value(line_2, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO 2: %s\n", strerror(errno));
        } else {
            printf("GPIO 2 set to 1\n");
        }

        // Toggle GPIO 17
        ret = gpiod_line_set_value(line_17, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO 17: %s\n", strerror(errno));
        } else {
            printf("GPIO 17 set to 1\n");
        }

        // Wait for 60 seconds
        sleep(INTERVAL);
    }

    // Clean up
    gpiod_line_release(line_2);
    gpiod_line_release(line_17);
    gpiod_chip_close(chip);

    return 0;

error_free_line_17:
    gpiod_line_release(line_17);
error_free_line_2:
    gpiod_line_release(line_2);
error_close_chip:
    gpiod_chip_close(chip);

    return 1;
}

