struct gpiod_line *line_2 = NULL;
struct gpiod_line *line_3 = NULL;
struct gpiod_line *line_17 = NULL;
int cycle_count = 0;
int exit_flag = 0;

void handle_signal(int sig) {
    exit_flag = 1;
}

void cleanup() {
    if (line_2) {
        gpiod_line_release(line_2);
    }
    if (line_3) {
