}

int main() {
    struct gpiod_chip *chip;
    int ret;

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Configure GPIO 2 (BCM 2)
    line_2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line_2) {
        fprintf(stderr, "Failed to get line for GPIO 2\n");
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_request_output(line_2, "gpio2-out", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line for GPIO 2: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure GPIO 3 (BCM 3)
    line_3 = gpiod_chip_get_line(chip, GPIO_PIN_3);
    if (!line_3) {
        fprintf(stderr, "Failed to get line for GPIO 3\n");
        gpiod_line_release(line_2);
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_request_output(line_3, "gpio3-out", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line for GPIO 3: %s\n", strerror(errno));
        gpiod_line_release(line_2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure GPIO 17 (BCM 17)
    line_17 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    if (!line_17) {
        fprintf(stderr, "Failed to get line for GPIO 17\n");
        gpiod_line_release(line_2);
        gpiod_line_release(line_3);
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_request_output(line_17, "gpio17-out", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line for GPIO 17: %s\n", strerror(errno));
        gpiod_line_release(line_2);
        gpiod_line_release(line_3);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (cycle_count < 3 && !exit_flag) {
        // Cycle 1: High, High, High
        gpiod_line_set_value(line_2, 1);
        gpiod_line_set_value(line_3, 1);
        gpiod_line_set_value(line_17, 1);
        printf("Cycle 1: All outputs set to 1\n");
        usleep(100000); // 100ms

        // Cycle 2: Low, Low, Low
        gpiod_line_set_value(line_2, 0);
        gpiod_line_set_value(line_3, 0);
        gpiod_line_set_value(line_17, 0);
        printf("Cycle 2: All outputs set to 0\n");
        usleep(100000); // 100ms

        // Cycle 3: High, Low, High
        gpiod_line_set_value(line_2, 1);
        gpiod_line_set_value(line_3, 0);
        gpiod_line_set_value(line_17, 1);
        printf("Cycle 3: GPIO 2 and 17 set to 1, GPIO 3 set to 0\n");
        usleep(100000); // 100ms

        cycle_count++;
    }

    // Cleanup
    cleanup();

    return 0;
}

