    if (!ctx) return;

    for (int i = 0; i < GPIO_COUNT; i++) {
        if (ctx->lines[i]) {
            gpiod_line_release(ctx->lines[i]);
        }
    }

    free(ctx);
}

static void handle_signal(int sig) {
    // Signal handler to clean up and exit
    printf("\nCaught signal %d, exiting...\n", sig);
    exit(EXIT_SUCCESS);
}

int main() {
    gpio_context *ctx = NULL;
    int line_index = 0;
    int ret;

    // Initialize signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Allocate context
    ctx = calloc(1, sizeof(gpio_context));
    if (!ctx) {
        fprintf(stderr, "Failed to allocate memory for GPIO context\n");
        return EXIT_FAILURE;
    }

    // Define GPIO pins in BCM numbering
    int gpio_pins[] = {GPIO_PIN_2, GPIO_PIN_3, GPIO_PIN_5, GPIO_PIN_17};

    // Open GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        cleanup_gpio(ctx);
        return EXIT_FAILURE;
    }

    // Request lines for each GPIO pin
    for (int i = 0; i < GPIO_COUNT; i++) {
        ctx->line_indices[i] = gpio_pins[i];
        ctx->lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!ctx->lines[i]) {
            fprintf(stderr, "Failed to get line for GPIO %d\n", gpio_pins[i]);
            cleanup_gpio(ctx);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
