        if (ret < 0) {
            fprintf(stderr, "Failed to request output for GPIO %d: %s\n", gpio_pins[i], strerror(errno));
            cleanup_gpio(ctx);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Main loop
    while (1) {
        // Toggle each GPIO pin
        for (int i = 0; i < GPIO_COUNT; i++) {
