#define DS18B20_DEVICE_PATH "/sys/bus/w1/devices/"
#define DS18B20_FILE_PATH "w1_slave"
#define NUM_READINGS 3
#define DELAY_SECONDS 5

volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void cleanup() {
    // No specific cleanup needed for sysfs-w1, but we can ensure the program exits cleanly
    printf("Cleanup complete.\n");
    exit(EXIT_SUCCESS);
}

int find_ds18b20_device() {
    DIR *dir;
    struct dirent *entry;
    char device_path[256];
    char full_path[256];

    dir = opendir(DS18B20_DEVICE_PATH);
    if (!dir) {
        perror("Failed to open 1-wire devices directory");
        return -1;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        snprintf(device_path, sizeof(device_path), "%s/%s/%s", DS18B20_DEVICE_PATH, entry->d_name, DS18B20_FILE_PATH);
        snprintf(full_path, sizeof(full_path), "%s/%s", DS18B20_DEVICE_PATH, entry->d_name);

        if (access(device_path, F_OK) == 0) {
            closedir(dir);
            printf("Found DS18B20 device at: %s\n", full_path);
            return 0;
        }
    }

    closedir(dir);
    fprintf(stderr, "DS18B20 device not found.\n");
    return -1;
}

double read_temperature(const char *device_path) {
    FILE *fp;
    char line[256];
    double temp = 0.0;

    fp = fopen(device_path, "r");
    if (!fp) {
        perror("Failed to open temperature file");
        return -1;
    }

    while (fgets(line, sizeof(line), fp)) {
        if (strstr(line, "t=")) {
            sscanf(line, "t=%lf", &temp);
            break;
        }
    }

    fclose(fp);
    return temp / 1000.0; // Convert from 1000ths of a degree Celsius
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (find_ds18b20_device() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    char device_path[256];
    DIR *dir;
    struct dirent *entry;

    dir = opendir(DS18B20_DEVICE_PATH);
    if (!dir) {
        perror("Failed to open 1-wire devices directory");
        cleanup();
        return EXIT_FAILURE;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        snprintf(device_path, sizeof(device_path), "%s/%s/%s", DS18B20_DEVICE_PATH, entry->d_name, DS18B20_FILE_PATH);

        if (access(device_path, F_OK) == 0) {
            break;
        }
    }

    closedir(dir);

    for (int i = 0; i < NUM_READINGS && running; i++) {
        double temperature = read_temperature(device_path);
        if (temperature == -1) {
            fprintf(stderr, "Failed to read temperature.\n");
            cleanup();
            return EXIT_FAILURE;
        }

        printf("Temperature reading %d: %.2f°C\n", i + 1, temperature);
        sleep(DELAY_SECONDS);
    }

    cleanup();
    return EXIT_SUCCESS;
}

