    exit(EXIT_FAILURE);
}

int main(int argc, char *argv[]) {
    struct gpiod_line *trig_line = NULL;
    struct gpiod_line *echo_line = NULL;
    struct gpiod_line *gnd_line = NULL;
    struct gpiod_chip *chip;
    int ret;

    if (argc != 1) {
        usage(argv[0]);
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        perror("Failed to get TRIG GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get ECHO GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gnd_line = gpiod_chip_get_line(chip, GND_PIN);
    if (!gnd_line) {
        perror("Failed to get GND GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(trig_line, "trig", GPIO_ACTIVE_LOW)) {
        perror("Failed to request TRIG GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(echo_line, "echo", 0)) {
        perror("Failed to request ECHO GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(gnd_line, "gnd", GPIO_ACTIVE_LOW)) {
        perror("Failed to request GND GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(gnd_line, 1); // Ensure GND is connected

    while (1) {
        // Trigger the HC-SR04
        gpiod_line_set_value(trig_line, 1);
        usleep(10); // Send 10us pulse
        gpiod_line_set_value(trig_line, 0);

        // Wait for echo to go high
        int echo_high = 0;
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);

        while (gpiod_line_get_value(echo_line) == 0 && (clock_gettime(CLOCK_MONOTONIC, &end), (end.tv_nsec - start.tv_nsec) < MAX_WAIT_US * 1000)) {
            usleep(1);
        }

        if (gpiod_line_get_value(echo_line) == 0) {
            printf("No echo received\n");
            usleep(100000); // Wait before next attempt
            continue;
        }

        // Measure echo duration
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(echo_line) == 1 && (clock_gettime(CLOCK_MONOTONIC, &end), (end.tv_nsec - start.tv_nsec) < MAX_WAIT_US * 1000)) {
            usleep(1);
        }

        long duration = end.tv_nsec - start.tv_nsec;
        if (duration < 0) duration += 1000000000;

        // Convert to distance in cm
        double distance_cm = (double)duration / 58.2; // Speed of sound = 343 m/s, 1m = 100cm, 1us = 0.000001s

        if (distance_cm > MAX_DISTANCE_CM) {
            printf("Distance: %f cm (out of range)\n", distance_cm);
        } else {
            printf("Distance: %f cm\n", distance_cm);
        }

        usleep(100000); // 0.1 seconds
    }

    // Cleanup
    gpiod_line_set_value(gnd_line, 0);
    gpiod_line_release(gnd_line);
    gpiod_line_release(echo_line);
    gpiod_line_release(trig_line);
    gpiod_chip_close(chip);

    return 0;
}

