#define GPIO_PIN 4
#define MAX_RETRIES 3
#define DHT22_DATA_PIN GPIO_PIN

// DHT22 signal protocol
#define DHT22_DATA_BIT 0
#define DHT22_DATA_BYTE 8
#define DHT22_DATA_LENGTH 40

// DHT22 signal timing
#define DHT22_DATA_HIGH 500
#define DHT22_DATA_LOW 500
#define DHT22_DATA_PULSE 100

// DHT22 checksum
#define DHT22_CHECKSUM (humidity + temperature)

// DHT22 data types
#define DHT22_HUMIDITY 0
#define DHT22_TEMPERATURE 1

// DHT22 data structure
typedef struct {
    uint8_t humidity;
    uint8_t temperature;
    uint8_t checksum;
} dht22_data_t;

// Function to wait for a specific time in microseconds
void delay_us(unsigned int us) {
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = us * 1000;
    nanosleep(&ts, NULL);
}

// Function to read DHT22 data
int read_dht22(gpio_line *line, dht22_data_t *data) {
    int i, j;
    int data_bit;
    int data_byte;
    int data_length;
    int data_value;
    int data_checksum;
    int data_valid = 0;

    // Send start signal
    gpio_line_set_value(line, 0);
    delay_us(DHT22_DATA_LOW);
    gpio_line_set_value(line, 1);
    delay_us(DHT22_DATA_HIGH);

    // Wait for response
    delay_us(DHT22_DATA_PULSE);

    // Read data
    for (i = 0; i < DHT22_DATA_LENGTH; i++) {
        // Wait for data bit
        while (gpio_line_get_value(line) == 1) {
            if (i == DHT22_DATA_LENGTH - 1) {
                return -1;
            }
        }

        // Read data bit
        delay_us(DHT22_DATA_PULSE);
        data_bit = gpio_line_get_value(line);
        delay_us(DHT22_DATA_PULSE);

        // Store data bit
        if (i % DHT22_DATA_BYTE == 0) {
            data_byte = 0;
            data_length = 0;
        }

        data_byte = (data_byte << 1) | data_bit;
        data_length++;

        if (data_length == DHT22_DATA_BYTE) {
            if (i < DHT22_DATA_LENGTH - 1) {
                if (i % DHT22_DATA_BYTE == 0) {
                    data->humidity = data_byte;
                } else {
                    data->temperature = data_byte;
                }
            } else {
                data_checksum = data_byte;
            }

            data_length = 0;
        }
    }

    // Check checksum
    if (data_checksum == DHT22_CHECKSUM) {
        data_valid = 1;
    }

    return data_valid;
}

int main() {
    int ret;
    int retry_count = 0;
    int cycles = 0;
    dht22_data_t data;
    struct gpiod_line *line;
    struct gpiod_line_request_config req_config;
    struct gpiod_line_request_config req_config_out;
    struct gpiod_line_request_config req_config_in;

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return -1;
    }

    // Open GPIO line
    line = gpiod_line_get("gpiochip4", GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_PIN);
        gpiod_exit();
        return -1;
    }

    // Configure line for output
    req_config_out = gpiod_line_request_config();
    req_config_out.consumer = "dht22";
    req_config_out.flags = GPIOD_LINE_REQUEST_FLAG_OUTPUT;
    req_config_out.default_value = 1;

    if (gpiod_line_request(line, &req_config_out) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d for output\n", GPIO_PIN);
        gpiod_line_put(line);
        gpiod_exit();
        return -1;
    }

    // Configure line for input
    req_config_in = gpiod_line_request_config();
    req_config_in.consumer = "dht22";
    req_config_in.flags = GPIOD_LINE_REQUEST_FLAG_INPUT;

    if (gpiod_line_request(line, &req_config_in) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d for input\n", GPIO_PIN);
        gpiod_line_put(line);
        gpiod_exit();
        return -1;
    }

    // Main loop
    while (cycles < 3) {
        // Reset data
        memset(&data, 0, sizeof(data));

        // Read DHT22 data
        ret = read_dht22(line, &data);

        if (ret < 0) {
            fprintf(stderr, "Failed to read DHT22 data\n");
            retry_count++;
            if (retry_count >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached, exiting\n");
                break;
            }
            continue;
        }

        if (ret == 0) {
            fprintf(stderr, "Invalid DHT22 data, retrying\n");
