#include <signal.h>

#define GPIO_PINS {4, 17, 18, 27}
#define NUM_PINS 4
#define CYCLES 5
#define CYCLE_DELAY 60

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

int main() {
    int i, pin;
    int *gpio_pins = GPIO_PINS;
    int cycle_count = 0;

    // Set up signal handler for graceful exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up GPIO pins for PWM output
    for (i = 0; i < NUM_PINS; i++) {
        pin = gpio_pins[i];
        if (gpioSetMode(pin, PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set mode for GPIO %d\n", pin);
            gpioTerminate();
            return 1;
        }
    }

    // Set PWM parameters
    int pwm_frequency = 1000; // 1 kHz
    int pwm_range = 100;      // 0-100%
    int duty_cycle = 50;      // 50% duty cycle

    for (i = 0; i < NUM_PINS; i++) {
        pin = gpio_pins[i];
        if (gpioSetPWMFrequency(pin, pwm_frequency) < 0) {
            fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", pin);
            gpioTerminate();
            return 1;
        }
        if (gpioPWM(pin, duty_cycle) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", pin);
            gpioTerminate();
            return 1;
        }
    }

    // Report initial state
    printf("PWM started on GPIOs 4, 17, 18, 27 with 50%% duty cycle.\n");

    while (running && cycle_count < CYCLES) {
        // Wait for cycle delay
        sleep(CYCLE_DELAY);

        // Stop PWM
        for (i = 0; i < NUM_PINS; i++) {
            pin = gpio_pins[i];
            if (gpioPWM(pin, 0) < 0) {
                fprintf(stderr, "Failed to stop PWM on GPIO %d\n", pin);
            }
        }

        // Report state
        printf("Cycle %d completed. PWM stopped.\n", cycle_count + 1);

        // Wait for a short period before restarting
        sleep(1);

        // Restart PWM
        for (i = 0; i < NUM_PINS; i++) {
            pin = gpio_pins[i];
            if (gpioPWM(pin, duty_cycle) < 0) {
                fprintf(stderr, "Failed to restart PWM on GPIO %d\n", pin);
            }
        }

        // Report state
        printf("Cycle %d started. PWM resumed.\n", cycle_count + 2);

        cycle_count++;
    }

    // Stop PWM and release resources
    for (i = 0; i < NUM_PINS; i++) {
        pin = gpio_pins[i];
        if (gpioPWM(pin, 0) < 0) {
            fprintf(stderr, "Failed to stop PWM on GPIO %d\n", pin);
        }
    }

    gpioTerminate();

    return 0;
}

