        fprintf(stderr, "Failed to request line 27 as output: %s\n", gpiod_strerror(ret));
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Toggle GPIO 17
        int value17 = gpiod_line_get_value(line17);
        ret = gpiod_line_set_value(line17, 1 - value17);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line 17: %s\n", gpiod_strerror(ret));
            break;
        }

        // Toggle GPIO 27
        int value27 = gpiod_line_get_value(line27);
        ret = gpiod_line_set_value(line27, 1 - value27);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line 27: %s\n", gpiod_strerror(ret));
            break;
        }

        // Report current state
        printf("GPIO 17: %d, GPIO 27: %d\n", value17, value27);
        fflush(stdout);

        // Wait for 5 seconds
        usleep(INTERVAL);
    }

    // Clean up
    gpiod_line_release(line17);
    gpiod_line_release(line27);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PINS 6
#define GPIO_PIN_LIST {17, 18, 22, 23, 24, 25}
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 50
#define UPDATE_INTERVAL 0.05

int main() {
    int pin;
    int *pwm_channels = NULL;
    int i;
    int result;

    // Initialize pigpio
    if ((result = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", gpioGetErrorString(result));
        return 1;
    }

    // Allocate memory for PWM channels
    pwm_channels = (int *)malloc(GPIO_PINS * sizeof(int));
    if (!pwm_channels) {
        fprintf(stderr, "Memory allocation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up PWM for each pin
    for (i = 0; i < GPIO_PINS; i++) {
        pin = GPIO_PIN_LIST[i];
        if (gpioSetMode(pin, PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set mode for GPIO %d\n", pin);
            free(pwm_channels);
            gpioTerminate();
            return 1;
        }

        if (gpioSetPWMFrequency(pin, PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", pin);
            free(pwm_channels);
            gpioTerminate();
            return 1;
        }

        pwm_channels[i] = pin;
    }

    // Main loop
    while (1) {
        // Set PWM duty cycle
        for (i = 0; i < GPIO_PINS; i++) {
            if (gpioPWM(pwm_channels[i], PWM_DUTY_CYCLE) < 0) {
                fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", pwm_channels[i]);
                free(pwm_channels);
                gpioTerminate();
                return 1;
            }
        }

        // Report state
        printf("PWM applied to GPIOs 17, 18, 22, 23, 24, 25 with duty cycle %d%%\n", PWM_DUTY_CYCLE);

        // Sleep for the update interval
        usleep((unsigned int)(UPDATE_INTERVAL * 1e6));
    }

    // Clean up on exit
    free(pwm_channels);
    gpioTerminate();
    return 0;
}

#include <stdio.h>
