#define GPIO_PIN_17 17
#define GPIO_PIN_23 23
#define GPIO_PIN_24 24

typedef struct {
    struct gpiod_line *line_17;
    struct gpiod_line *line_23;
    struct gpiod_line *line_24;
    int running;
} gpio_state;

void cleanup_gpio(gpio_state *state) {
    if (state->line_17) {
        gpiod_line_release(state->line_17);
    }
    if (state->line_23) {
        gpiod_line_release(state->line_23);
    }
    if (state->line_24) {
        gpiod_line_release(state->line_24);
    }
    state->running = 0;
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal, cleaning up and exiting...\n");
        cleanup_gpio(NULL);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    gpio_state state = {0};
    struct gpiod_chip *chip;
    int ret;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Configure GPIO 17 as output
    state.line_17 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    if (!state.line_17) {
        fprintf(stderr, "Failed to get line 17\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(state.line_17, "gpio-out-17", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line 17 as output: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure GPIO 23 as output
    state.line_23 = gpiod_chip_get_line(chip, GPIO_PIN_23);
    if (!state.line_23) {
        fprintf(stderr, "Failed to get line 23\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(state.line_23, "gpio-out-23", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line 23 as output: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure GPIO 24 as output
    state.line_24 = gpiod_chip_get_line(chip, GPIO_PIN_24);
    if (!state.line_24) {
        fprintf(stderr, "Failed to get line 24\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(state.line_24, "gpio-out-24", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line 24 as output: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    state.running = 1;

    while (state.running) {
        // Toggle GPIO 17
        int val_17 = gpiod_line_get_value(state.line_17);
        if (val_17 < 0) {
            fprintf(stderr, "Failed to get value of line 17: %s\n", strerror(-val_17));
            cleanup_gpio(&state);
            break;
        }
        printf("GPIO 17: %d\n", val_17);

        // Toggle GPIO 23
        int val_23 = gpiod_line_get_value(state.line_23);
        if (val_23 < 0) {
            fprintf(stderr, "Failed to get value of line 23: %s\n", strerror(-val_23));
            cleanup_gpio(&state);
            break;
        }
        printf("GPIO 23: %d\n", val_23);

        // Toggle GPIO 24
        int val_24 = gpiod_line_get_value(state.line_24);
        if (val_24 < 0) {
            fprintf(stderr, "Failed to get value of line 24: %s\n", strerror(-val_24));
            cleanup_gpio(&state);
            break;
        }
        printf("GPIO 24: %d\n", val_24);

        // Wait for 1 second
        usleep(1000000);
    }

    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <libgpiod.h>

#define GPIO_PIN_DATA 4
#define GPIO_PIN_CLK 17
#define REPEAT_COUNT 3
#define DELAY_SECONDS 60

typedef struct {
    struct gpiod_line *data_line;
    struct gpiod_line *clk_line;
} gpio_pins;

int init_gpio(gpio_pins *pins) {
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    pins->data_line = gpiod_line_get(chip, GPIO_PIN_DATA);
    if (!pins->data_line) {
        perror("Failed to get data line");
        gpiod_chip_close(chip);
        return -1;
    }

    pins->clk_line = gpiod_line_get(chip, GPIO_PIN_CLK);
    if (!pins->clk_line) {
        perror("Failed to get clock line");
        gpiod_line_put(pins->data_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(pins->data_line, "dht22_data", GPIO_LINE_FLAG_ACTIVE_LOW)) {
        perror("Failed to request data line");
        gpiod_line_put(pins->data_line);
        gpiod_line_put(pins->clk_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(pins->clk_line, "dht22_clock", GPIO_LINE_FLAG_ACTIVE_LOW)) {
        perror("Failed to request clock line");
        gpiod_line_put(pins->data_line);
        gpiod_line_put(pins->clk_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

void release_gpio(gpio_pins *pins) {
    gpiod_line_put(pins->data_line);
    gpiod_line_put(pins->clk_line);
    gpiod_chip_close(gpiod_line_get_chip(pins->data_line));
}

int read_dht22(gpio_pins *pins, int *humidity, int *temperature) {
    int data[5] = {0};
    int i, j;
    int data_bit = 0;

    // Set data line high
    gpiod_line_set_value(pins->data_line, 1);
    usleep(20000);

    // Pull data line low
    gpiod_line_set_value(pins->data_line, 0);
    usleep(1000);

    // Send start signal
    gpiod_line_set_value(pins->clk_line, 1);
    usleep(1000);
    gpiod_line_set_value(pins->clk_line, 0);
    usleep(1000);

    // Read data
    for (i = 0; i < 40; i++) {
        // Wait for data line to go high
        while (gpiod_line_get_value(pins->data_line) == 0) {
            if (i == 39) {
                return -1; // Timeout
            }
        }

        // Wait for data line to go low
        while (gpiod_line_get_value(pins->data_line) == 1) {
            if (i == 39) {
                return -1; // Timeout
            }
        }

        // Read data bit
        usleep(30);
        data_bit = gpiod_line_get_value(pins->data_line);

        // Clock pulse
        gpiod_line_set_value(pins->clk_line, 1);
        usleep(10);
        gpiod_line_set_value(pins->clk_line, 0);
        usleep(10);

        data[i / 8] <<= 1;
        if (data_bit) {
            data[i / 8] |= 0x01;
        }
    }

    // Check checksum
    if ((data[0] + data[1] + data[2]) != data[3]) {
        return -1; // Invalid checksum
    }

    *humidity = data[0];
    *temperature = data[2];

    return 0;
}

void signal_handler(int sig) {
    // Release GPIO and exit
    release_gpio(&pins);
    exit(EXIT_SUCCESS);
}

int main() {
    gpio_pins pins;
    int humidity, temperature;
    int cycle = 0;
    int ret;

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_gpio(&pins) != 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    while (cycle < REPEAT_COUNT) {
        ret = read_dht22(&pins, &humidity, &temperature);
        if (ret == 0) {
            printf("Cycle %d: Humidity = %d, Temperature = %d\n", cycle + 1, humidity, temperature);
        } else {
            fprintf(stderr, "Cycle %d: Failed to read DHT22 data\n", cycle + 1);
        }

        // Wait for the next cycle
        sleep(DELAY_SECONDS);

        cycle++;
    }

    release_gpio(&pins);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <gpiod.h>

#define GPIO_COUNT 5
#define GPIO_PINS {8, 9, 10, 11, 23}

int main() {
    struct gpiod_line *lines[GPIO_COUNT];
    struct gpiod_line_request_config config;
    int i, cycle = 0;
    int ret;

    // Initialize line request configuration
    memset(&config, 0, sizeof(config));
    config.request_type = GPIOD_LINE_REQUEST_TYPE_OUTPUT;
    config.output_value = 0;

    // Open GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines
    for (i = 0; i < GPIO_COUNT; i++) {
        lines[i] = gpiod_line_request(chip, GPIO_PINS[i], "output", &config);
        if (!lines[i]) {
            perror("Failed to request GPIO line");
            goto error_cleanup;
        }
    }

    // Main loop
    while (cycle < 3) {
        for (i = 0; i < GPIO_COUNT; i++) {
            gpiod_line_set_value(lines[i], 1);
            printf("GPIO %d set to 1\n", GPIO_PINS[i]);
            usleep(500000); // 0.5 seconds
            gpiod_line_set_value(lines[i], 0);
            printf("GPIO %d set to 0\n", GPIO_PINS[i]);
            usleep(500000); // 0.5 seconds
        }
        cycle++;
        sleep(1); // 1 second between cycles
    }

    // Cleanup
    for (i = 0; i < GPIO_COUNT; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;

error_cleanup:
    for (int j = 0; j < i; j++) {
        gpiod_line_release(lines[j]);
    }
    gpiod_chip_close(chip);
    return EXIT_FAILURE;
}

#include <stdio.h>
