#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PWM_17 17
#define GPIO_PWM_18 18
#define GPIO_PWM_27 27

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    // Set up PWM on GPIO 17, 18, 27
    if (gpioSetMode(GPIO_PWM_17, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO_PWM_18, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO_PWM_27, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    // Set PWM parameters
    if (gpioSetPWMFrequency(GPIO_PWM_17, 1000) < 0 ||
        gpioSetPWMFrequency(GPIO_PWM_18, 1000) < 0 ||
        gpioSetPWMFrequency(GPIO_PWM_27, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        // Set PWM duty cycle (0-100)
        int duty_cycle = 50; // 50% duty cycle

        if (gpioPWM(GPIO_PWM_17, duty_cycle) < 0 ||
            gpioPWM(GPIO_PWM_18, duty_cycle) < 0 ||
            gpioPWM(GPIO_PWM_27, duty_cycle) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
            gpioTerminate();
            return 1;
        }

        printf("PWM applied to GPIO 17, 18, 27 with duty cycle %d%%\n", duty_cycle);
        fflush(stdout);

        sleep(1);
    }

    // Clean up
    gpioPWM(GPIO_PWM_17, 0);
    gpioPWM(GPIO_PWM_18, 0);
    gpioPWM(GPIO_PWM_27, 0);

    gpioTerminate();

    return 0;
}

