#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_DELAY 0

#define MAX31855_READ_COMMAND 0x01
#define MAX31855_DATA_SIZE 3

int spi_fd = -1;

void spi_init() {
    spi_fd = open(SPI_DEVICE, O_RDWR | O_SYNC);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.fd = spi_fd;
    spi.speed_hz = SPI_SPEED;
    spi.bits_per_word = SPI_BITS;
    spi.delay_usecs = SPI_DELAY;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

void spi_transfer(unsigned char *tx, unsigned char *rx, size_t len) {
    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.fd = spi_fd;
    spi.speed_hz = SPI_SPEED;
    spi.bits_per_word = SPI_BITS;
    spi.delay_usecs = SPI_DELAY;
    spi.tx_buf = (unsigned long)tx;
    spi.rx_buf = (unsigned long)rx;
    spi.len = len;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("SPI transfer failed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

void spi_close() {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

int main() {
    unsigned char tx[1] = {MAX31855_READ_COMMAND};
    unsigned char rx[MAX31855_DATA_SIZE];

    spi_init();

    spi_transfer(tx, rx, sizeof(rx));

    // Extract temperature data
    unsigned int config = (rx[0] << 8) | rx[1];
    unsigned int thermocouple = (rx[0] << 8) | rx[2];

    // Check for error flags
    if (config & 0x80) {
        fprintf(stderr, "Error: Configuration error\n");
        spi_close();
        exit(EXIT_FAILURE);
    }

    if (config & 0x40) {
        fprintf(stderr, "Error: Thermocouple error\n");
        spi_close();
        exit(EXIT_FAILURE);
    }

    // Calculate temperature
    int16_t temp = (int16_t)(thermocouple >> 4);
    temp = temp * 0.0625; // 0.0625°C per count

    // Check if temperature is within valid range
    if (temp < -200 || temp > 1370) {
        fprintf(stderr, "Error: Temperature out of range\n");
        spi_close();
        exit(EXIT_FAILURE);
    }

    printf("Temperature: %.2f°C\n", (double)temp);

    spi_close();
    return 0;
}

