#include <linux/gpio.h>
#include <libgpiod.h>

#define TRIG_PIN 4
#define ECHO_PIN 17
#define LED_PIN 18
#define LED_PIN2 27

#define MAX_WAIT_US 500000  // 0.5 seconds
#define MAX_DISTANCE_CM 400

int main() {
    struct gpiod_line *trig_line = NULL;
    struct gpiod_line *echo_line = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *led_line2 = NULL;
    struct gpiod_chip *chip = NULL;
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Configure TRIG pin (output)
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        fprintf(stderr, "Failed to get TRIG line\n");
        goto error_close_chip;
    }

    ret = gpiod_line_request_output(trig_line, "trig", GPIO_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request TRIG line as output: %s\n", strerror(-ret));
        goto error_close_line_trig;
    }

    // Configure ECHO pin (input)
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get ECHO line\n");
        goto error_close_line_trig;
    }

    ret = gpiod_line_request_input(echo_line, "echo", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request ECHO line as input: %s\n", strerror(-ret));
        goto error_close_line_echo;
    }

    // Configure LED pins (output)
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        goto error_close_line_echo;
    }

    ret = gpiod_line_request_output(led_line, "led", GPIO_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(-ret));
        goto error_close_line_led;
    }

    led_line2 = gpiod_chip_get_line(chip, LED_PIN2);
    if (!led_line2) {
        fprintf(stderr, "Failed to get LED2 line\n");
        goto error_close_line_led;
    }

    ret = gpiod_line_request_output(led_line2, "led2", GPIO_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request LED2 line as output: %s\n", strerror(-ret));
        goto error_close_line_led2;
    }

    // Send a trigger pulse
    gpiod_line_set_value(trig_line, 1);
    usleep(10);  // 10 microseconds
    gpiod_line_set_value(trig_line, 0);

    // Wait for echo signal
    int echo_state = 0;
    int start_time = 0;
    int end_time = 0;
    int timeout = 0;

    // Wait for echo to go high
    while (timeout < MAX_WAIT_US) {
        echo_state = gpiod_line_get_value(echo_line);
        if (echo_state == 1) {
            start_time = gettime();
            break;
        }
        usleep(1);
        timeout += 1;
    }

    if (echo_state != 1) {
        fprintf(stderr, "No echo signal received\n");
        goto error_close_all;
    }

    // Wait for echo to go low
    while (timeout < MAX_WAIT_US) {
        echo_state = gpiod_line_get_value(echo_line);
        if (echo_state == 0) {
            end_time = gettime();
            break;
        }
        usleep(1);
        timeout += 1;
    }

    if (echo_state != 0) {
        fprintf(stderr, "Echo signal did not return\n");
        goto error_close_all;
    }

    // Calculate distance
    long duration = end_time - start_time;
    double distance_cm = (duration * 0.0343) / 2;

    if (distance_cm > MAX_DISTANCE_CM) {
        printf("Object out of range\n");
        gpiod_line_set_value(led_line, 1);
        gpiod_line_set_value(led_line2, 1);
    } else {
        printf("Distance: %.2f cm\n", distance_cm);
        gpiod_line_set_value(led_line, 0);
        gpiod_line_set_value(led_line2, 0);
    }

    // Cleanup
    gpiod_line_set_value(led_line, 0);
    gpiod_line_set_value(led_line2, 0);

error_close_all:
