error_close_line_led2:
    gpiod_line_release(led_line);
error_close_line_led:
    gpiod_line_release(echo_line);
error_close_line_echo:
    gpiod_line_release(trig_line);
error_close_line_trig:
    gpiod_chip_close(chip);
error_close_chip:
    return 0;
}

