#define BMP280_REGISTER_CONTROL 0xF4
#define BMP280_REGISTER_PRESSURE_DATA 0xF7
#define BMP280_REGISTER_TEMP_DATA 0xF8
#define BMP280_REGISTER_CHIP_ID 0xD0
#define BMP280_CHIP_ID 0x58

typedef struct {
    uint32_t pressure;
    int32_t temperature;
} bmp280_data_t;

int open_i2c_bus(const char *device) {
    int file;
    if ((file = open(device, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return -1;
    }
    return file;
}

int i2c_write_reg(int file, uint8_t reg, uint8_t val) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = val;
    if (write(file, buffer, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int i2c_read_regs(int file, uint8_t reg, uint8_t *buffer, size_t len) {
    if (ioctl(file, I2C_SLAVE, BMP280_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }
    if (read(file, buffer, len) != len) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

void calculate_pressure_and_temperature(uint8_t *data, bmp280_data_t *result) {
    int32_t var1, var2;
    int32_t temp;
    int32_t pressure;
    int32_t temp_fine;

    // Read temperature
    temp = (int32_t)((data[3] << 12) | (data[2] << 4) | (data[1] >> 4));
    var1 = ((temp / 4) - (12800)) * ((temp / 4) - (12800));
    var1 = var1 * 3048;
    var1 = var1 / 10000000;
    var1 = var1 + 20000;
    temp_fine = temp / 4;
    var2 = (int32_t)(data[0] * 2000) / 100;
    temp_fine = temp_fine + var2;
    temp = (temp_fine * 5 + 32768) / 10;

    // Read pressure
    pressure = (int32_t)((data[5] << 12) | (data[4] << 4) | (data[3] >> 4));
    var1 = (int32_t)(temp_fine - 2000) * (int32_t)(temp_fine - 2000);
    var1 = var1 * 3048;
    var1 = var1 / 10000000;
