#define I2C_BUS "/dev/i2c-1"
#define BME280_I2C_ADDR 0x76
#define NUM_READINGS 3
#define INTERVAL_SECONDS 5

typedef struct {
    int fd;
    int i2c_bus;
    int i2c_addr;
} i2c_dev;

void i2c_init(i2c_dev *dev) {
    dev->i2c_bus = open(I2C_BUS, O_RDWR);
    if (dev->i2c_bus < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(dev->i2c_bus, I2C_SLAVE, dev->i2c_addr) < 0) {
        perror("Failed to set I2C slave address");
        close(dev->i2c_bus);
        exit(EXIT_FAILURE);
    }
}

void i2c_close(i2c_dev *dev) {
    close(dev->i2c_bus);
}

void i2c_read(i2c_dev *dev, unsigned char *buf, int len) {
    if (read(dev->i2c_bus, buf, len) != len) {
        perror("Failed to read from I2C device");
        exit(EXIT_FAILURE);
    }
}

void i2c_write(i2c_dev *dev, unsigned char *buf, int len) {
    if (write(dev->i2c_bus, buf, len) != len) {
        perror("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }
}

void signal_handler(int signal) {
    printf("\nInterrupt received, exiting...\n");
    exit(EXIT_FAILURE);
}

int main() {
    i2c_dev dev;
    dev.i2c_bus = -1;
    dev.i2c_addr = BME280_I2C_ADDR;

    // Register signal handler for graceful exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_init(&dev);

    // BME280 calibration data and settings
    unsigned char calib_data[24];
    unsigned char config[2] = {0x21, 0x01}; // 0x21: 0x01 for normal mode, 0x01 for 1x oversampling
    unsigned char ctrl_meas[2] = {0x21, 0x01}; // 0x21: 0x01 for normal mode, 0x01 for 1x oversampling

    // Write configuration
    i2c_write(&dev, config, 2);
    i2c_write(&dev, ctrl_meas, 2);

    // Read calibration data
    i2c_read(&dev, calib_data, 24);

    // Read temperature and humidity
    unsigned char temp_data[6];
    unsigned char hum_data[6];

    for (int i = 0; i < NUM_READINGS; i++) {
        // Trigger measurement
        i2c_write(&dev, ctrl_meas, 2);

        // Wait for measurement to complete
        sleep(1);

        // Read temperature data
        i2c_read(&dev, temp_data, 6);

        // Read humidity data
        i2c_read(&dev, hum_data, 6);

        // Calculate temperature
        int16_t temp = (temp_data[0] << 8) | temp_data[1];
        int16_t temp_fine = (temp_data[3] << 8) | temp_data[4];
        int32_t temp_cal = (int32_t)temp_fine;
        temp_cal = (temp_cal * 16 + 128) >> 15;
        temp = (temp_cal * 5 + 128) >> 15;

        // Calculate humidity
        int16_t hum = (hum_data[0] << 8) | hum_data[1];
        hum = (hum * 100 + 500) >> 10;

        // Print readings
        printf("Reading %d:\n", i + 1);
        printf("Temperature: %.2f C\n", (double)temp / 100);
        printf("Humidity: %.2f %%\n", (double)hum / 100);
        printf("-----------------------------\n");

        // Sleep between readings
        sleep(INTERVAL_SECONDS);
    }

    // Clean up
    i2c_close(&dev);
    return 0;
}

