typedef struct {
    int fd;
    struct termios orig_termios;
} UartContext;

void cleanup_uart(UartContext *ctx) {
    if (ctx->fd >= 0) {
        tcsetattr(ctx->fd, TCSAFLUSH, &ctx->orig_termios);
        close(ctx->fd);
    }
}

void handle_signal(int sig) {
    // Signal handler to clean up and exit
    printf("\nCaught signal %d, exiting...\n", sig);
    exit(EXIT_FAILURE);
}

int open_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        perror("Failed to open UART device");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Failed to get terminal attributes");
        close(fd);
        return -1;
    }

    // Save original attributes
    memcpy(&tty, &ctx.orig_termios, sizeof(tty));

    // Set baud rate
    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    // Set data bits, parity, stop bits
    tty.c_cflag &= ~CSIZE; // Clear data size mask
    tty.c_cflag |= CS8;    // 8 bits per character
    tty.c_cflag &= ~PARENB; // No parity
    tty.c_cflag &= ~CSTOPB; // 1 stop bit
    tty.c_cflag &= ~CRTSCTS; // No hardware flow control

    // Enable receiver and set local mode
    tty.c_cflag |= (CLOCAL | CREAD);

    // Set raw input mode
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_oflag &= ~OPOST;

    // Set input and output timeouts
    tty.c_cc[VMIN] = 0; // Minimum number of bytes to read
    tty.c_cc[VTIME] = 0; // Timeout in tenths of a second

    if (tcsetattr(fd, TCSAFLUSH, &tty) != 0) {
        perror("Failed to set terminal attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_uart(int fd, char *buffer, size_t size) {
    int n = read(fd, buffer, size);
    if (n < 0) {
        perror("UART read failed");
        return -1;
    } else if (n == 0) {
        // No data received
        return 0;
    } else {
        buffer[n] = '\0';
        return n;
    }
}

int main() {
    UartContext ctx = {0};
    char read_buffer[READ_BUFFER_SIZE];

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open UART
    ctx.fd = open_uart(UART_DEVICE);
    if (ctx.fd < 0) {
        fprintf(stderr, "UART device not found or inaccessible.\n");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Read from UART
        int bytes_read = read_uart(ctx.fd, read_buffer, sizeof(read_buffer));
        if (bytes_read > 0) {
            printf("Received: %s\n", read_buffer);
        } else {
            // No data received, wait for a short time before trying again
            usleep(100000); // 0.1 seconds
        }

        // Sleep for 0.1 seconds
        usleep(100000);
    }

    // Cleanup on exit
    cleanup_uart(&ctx);
    return 0;
}

