    line_17 = gpiod_line_request(GPIO_PIN_17, &req);
    if (!line_17) {
        fprintf(stderr, "Failed to request GPIO 17\n");
        exit(EXIT_FAILURE);
    }

    // GPIO 18
    line_18 = gpiod_line_request(GPIO_PIN_18, &req);
    if (!line_18) {
        fprintf(stderr, "Failed to request GPIO 18\n");
        gpiod_line_release(line_17);
        exit(EXIT_FAILURE);
    }

    // GPIO 22
    line_22 = gpiod_line_request(GPIO_PIN_22, &req);
    if (!line_22) {
        fprintf(stderr, "Failed to request GPIO 22\n");
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        exit(EXIT_FAILURE);
    }

    // GPIO 27
    line_27 = gpiod_line_request(GPIO_PIN_27, &req);
    if (!line_27) {
        fprintf(stderr, "Failed to request GPIO 27\n");
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_line_release(line_22);
        exit(EXIT_FAILURE);
    }

    // Set all lines to output
    ret = gpiod_line_set_direction(line_17, GPIOD_LINE_DIRECTION_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO 17 direction: %s\n", strerror(errno));
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_line_release(line_22);
        gpiod_line_release(line_27);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_set_direction(line_18, GPIOD_LINE_DIRECTION_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO 18 direction: %s\n", strerror(errno));
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_line_release(line_22);
        gpiod_line_release(line_27);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_set_direction(line_22, GPIOD_LINE_DIRECTION_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO 22 direction: %s\n", strerror(errno));
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_line_release(line_22);
        gpiod_line_release(line_27);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_set_direction(line_27, GPIOD_LINE_DIRECTION_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO 27 direction: %s\n", strerror(errno));
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_line_release(line_22);
        gpiod_line_release(line_27);
        exit(EXIT_FAILURE);
    }

    // Toggle and report state every 0.5 seconds
    while (1) {
        // Toggle all GPIOs
        gpiod_line_set_value(line_17, 1);
        gpiod_line_set_value(line_18, 0);
        gpiod_line_set_value(line_22, 1);
        gpiod_line_set_value(line_27, 0);

        printf("GPIO 17: 1, GPIO 18: 0, GPIO 22: 1, GPIO 27: 0\n");
        fflush(stdout);

        sleep(1);

        gpiod_line_set_value(line_17, 0);
        gpiod_line_set_value(line_18, 1);
        gpiod_line_set_value(line_22, 0);
        gpiod_line_set_value(line_27, 1);

        printf("GPIO 17: 0, GPIO 18: 1, GPIO 22: 0, GPIO 27: 1\n");
        fflush(stdout);

        sleep(1);
    }

    // Clean up on exit
    gpiod_line_release(line_17);
    gpiod_line_release(line_18);
    gpiod_line_release(line_22);
    gpiod_line_release(line_27);

    return 0;
}

