#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <gpiod.h>
#include <signal.h>

#define GPIO_PINS 8
#define GPIO_PIN_LIST {0, 1, 2, 3, 4, 5, 12, 17}

typedef struct {
    struct gpiod_line *lines[GPIO_PINS];
    int line_count;
} gpio_context;

void cleanup_gpio(gpio_context *ctx) {
    if (ctx->line_count > 0) {
        for (int i = 0; i < ctx->line_count; i++) {
            gpiod_line_release(ctx->lines[i]);
        }
    }
}

void handle_signal(int sig) {
    cleanup_gpio(NULL);
    exit(EXIT_SUCCESS);
}

int main() {
    gpio_context ctx = {0};
    int pin;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %m\n");
        return EXIT_FAILURE;
    }

    // Initialize GPIO lines
    ctx.line_count = 0;
    for (int i = 0; i < GPIO_PINS; i++) {
        pin = GPIO_PIN_LIST[i];
        line = gpiod_chip_get_line(chip, pin);
        if (!line) {
            fprintf(stderr, "Failed to get line %d: %m\n", pin);
            cleanup_gpio(&ctx);
            return EXIT_FAILURE;
        }

        // Configure line as output
        ret = gpiod_line_request_output(line, "gpio_output", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %d: %m\n", pin);
            cleanup_gpio(&ctx);
            return EXIT_FAILURE;
        }

        ctx.lines[ctx.line_count++] = line;
    }

    // Main loop
    while (1) {
        for (int i = 0; i < ctx.line_count; i++) {
            line = ctx.lines[i];
            int value = gpiod_line_get_value(line);
            if (value < 0) {
                fprintf(stderr, "Failed to get value for line %d: %m\n", GPIO_PIN_LIST[i]);
                cleanup_gpio(&ctx);
                return EXIT_FAILURE;
            }
            printf("GPIO %d: %d\n", GPIO_PIN_LIST[i], value);
        }

        // Toggle all lines
        for (int i = 0; i < ctx.line_count; i++) {
            line = ctx.lines[i];
            int value = gpiod_line_get_value(line);
            if (value < 0) {
                fprintf(stderr, "Failed to get value for line %d: %m\n", GPIO_PIN_LIST[i]);
                cleanup_gpio(&ctx);
                return EXIT_FAILURE;
            }
            int new_value = (value == 0) ? 1 : 0;
            ret = gpiod_line_set_value(line, new_value);
            if (ret < 0) {
                fprintf(stderr, "Failed to set value for line %d: %m\n", GPIO_PIN_LIST[i]);
                cleanup_gpio(&ctx);
                return EXIT_FAILURE;
            }
        }

        sleep(1);
    }

    // Should not reach here, but just in case
    cleanup_gpio(&ctx);
    return EXIT_SUCCESS;
}

