#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <libgpiod.h>

#define GPIO_PIN_17 17
#define GPIO_PIN_27 27
#define INTERVAL_MS 200

int main() {
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line27 = NULL;
    struct gpiod_line_request_config req17;
    struct gpiod_line_request_config req27;
    int ret;

    // Initialize line request for GPIO 17
    gpiod_line_request_config_init(&req17);
    req17.line = GPIO_PIN_17;
    req17.consumer = "gpio17_output";
    req17.flags = GPIOD_LINE_REQUEST_OUTPUT;

    // Initialize line request for GPIO 27
    gpiod_line_request_config_init(&req27);
    req27.line = GPIO_PIN_27;
    req27.consumer = "gpio27_output";
    req27.flags = GPIOD_LINE_REQUEST_OUTPUT;

    // Open the GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open(-1);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request GPIO 17
    line17 = gpiod_line_request(chip, &req17);
    if (!line17) {
        fprintf(stderr, "Failed to request GPIO 17\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO 27
    line27 = gpiod_line_request(chip, &req27);
    if (!line27) {
        fprintf(stderr, "Failed to request GPIO 27\n");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set initial state
    gpiod_line_set_value(line17, 0);
    gpiod_line_set_value(line27, 0);

    // Report initial state
    printf("Initial state: GPIO 17 = 0, GPIO 27 = 0\n");

    // Main loop
    while (1) {
        // Toggle GPIO 17
        gpiod_line_set_value(line17, 1 - gpiod_line_get_value(line17));
        // Toggle GPIO 27
        gpiod_line_set_value(line27, 1 - gpiod_line_get_value(line27));

        // Report current state
        int val17 = gpiod_line_get_value(line17);
        int val27 = gpiod_line_get_value(line27);
        printf("State: GPIO 17 = %d, GPIO 27 = %d\n", val17, val27);

        // Sleep for 0.2 seconds
        usleep(INTERVAL_MS * 1000);

        // Check for interrupt (Ctrl+C)
        if (signal(SIGINT, SIG_IGN) == SIG_ERR) {
            fprintf(stderr, "Failed to ignore SIGINT\n");
            break;
        }
    }

    // Clean up
    gpiod_line_release(line17);
    gpiod_line_release(line27);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <libgpiod.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define GND_PIN 27

int main() {
    struct gpiod_line *trig_line = NULL;
    struct gpiod_line *echo_line = NULL;
    struct gpiod_line *gnd_line = NULL;
    int ret;

    // Initialize libgpiod
    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Configure TRIG pin (output)
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        fprintf(stderr, "Failed to get TRIG line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(trig_line, "trig", GPIO_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request TRIG line: %s\n", strerror(-ret));
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure ECHO pin (input)
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get ECHO line\n");
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_input(echo_line, "echo", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request ECHO line: %s\n", strerror(-ret));
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure GND pin (output, but used as ground, so set to low)
    gnd_line = gpiod_chip_get_line(chip, GND_PIN);
    if (!gnd_line) {
        fprintf(stderr, "Failed to get GND line\n");
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(gnd_line, "gnd", GPIO_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GND line: %s\n", strerror(-ret));
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(gnd_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set GND pin to low (ground)
    ret = gpiod_line_set_value(gnd_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GND line: %s\n", strerror(-ret));
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(gnd_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Send 10us pulse to TRIG pin
    ret = gpiod_line_set_value(trig_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set TRIG line high: %s\n", strerror(-ret));
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(gnd_line);
        gpiod_chip_close(chip);
        return 1;
    }

    usleep(10000); // 10ms pulse

    ret = gpiod_line_set_value(trig_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set TRIG line low: %s\n", strerror(-ret));
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(gnd_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Wait for ECHO pin to go high
    int echo_high = 0;
    while (gpiod_line_get_value(echo_line) == 0) {
        if (usleep(1000) < 0) {
            fprintf(stderr, "Failed to sleep: %s\n", strerror(errno));
            gpiod_line_release(trig_line);
            gpiod_line_release(echo_line);
            gpiod_line_release(gnd_line);
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Measure time until ECHO pin goes low
    long start_time = 0;
    long end_time = 0;
    long duration = 0;

    start_time = time(NULL);
    while (gpiod_line_get_value(echo_line) == 1) {
        if (usleep(1000) < 0) {
            fprintf(stderr, "Failed to sleep: %s\n", strerror(errno));
            gpiod_line_release(trig_line);
            gpiod_line_release(echo_line);
            gpiod_line_release(gnd_line);
            gpiod_chip_close(chip);
            return 1;
        }
    }
    end_time = time(NULL);

    duration = end_time - start_time;

    // Convert to centimeters (speed of sound = 0.0343 cm/us)
    double distance_cm = duration * 0.0343;

    printf("Distance: %.2f cm\n", distance_cm);

    // Release resources
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_line_release(gnd_line);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>

#define GPIO_PWM_18 18
#define GPIO_PWM_21 21
#define GPIO_PWM_22 22

int running = 1;

void signal_handler(int signal) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    // Set up PWM on GPIO 18, 21, 22
    if (gpioSetMode(GPIO_PWM_18, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", GPIO_PWM_18);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_PWM_21, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", GPIO_PWM_21);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_PWM_22, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", GPIO_PWM_22);
        gpioTerminate();
        return 1;
    }

    // Set PWM parameters
    int pwm_frequency = 1000; // 1 kHz
    if (gpioSetPWMFrequency(GPIO_PWM_18, pwm_frequency) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", GPIO_PWM_18);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMFrequency(GPIO_PWM_21, pwm_frequency) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", GPIO_PWM_21);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMFrequency(GPIO_PWM_22, pwm_frequency) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", GPIO_PWM_22);
        gpioTerminate();
        return 1;
    }

    // Set PWM duty cycle (0-100)
    int duty_cycle = 50;
    if (gpioSetPWMdutyCycle(GPIO_PWM_18, duty_cycle) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", GPIO_PWM_18);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMdutyCycle(GPIO_PWM_21, duty_cycle) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", GPIO_PWM_21);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMdutyCycle(GPIO_PWM_22, duty_cycle) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", GPIO_PWM_22);
        gpioTerminate();
        return 1;
    }

    // Report the state
    printf("PWM applied to GPIO 18, 21, 22 with frequency %d Hz and duty cycle %d%%\n", pwm_frequency, duty_cycle);

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Wait for signal to exit
    while (running) {
        sleep(1);
    }

    // Clean up
    gpioSetPWMdutyCycle(GPIO_PWM_18, 0);
    gpioSetPWMdutyCycle(GPIO_PWM_21, 0);
    gpioSetPWMdutyCycle(GPIO_PWM_22, 0);

    gpioTerminate();

    return 0;
}

