    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request lines for each GPIO pin
    for (i = 0; i < 7; i++) {
        pin = GPIO_PINS[i];
        lines[i] = gpiod_chip_get_line(chip, pin);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for GPIO %d\n", pin);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
