        if (gpiod_line_request_output(lines[i], "gpio-output", 0) < 0) {
            fprintf(stderr, "Failed to request output for GPIO %d\n", pin);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Set each GPIO pin to high (1)
    for (i = 0; i < 7; i++) {
        pin = GPIO_PINS[i];
        if (gpiod_line_set_value(lines[i], 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d to high\n", pin);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
