    echo_req.consumer = "hc-sr04_echo";
    echo_req.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;
    echo_req.direction = GPIOD_LINE_DIRECTION_INPUT;

    led_req.consumer = "hc-sr04_led";
    led_req.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;
    led_req.direction = GPIOD_LINE_DIRECTION_OUTPUT;
    led_req.output = 0;

    // Open GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request lines
    trig_line = gpiod_chip_request_line(chip, TRIG_PIN);
    if (!trig_line) {
        fprintf(stderr, "Failed to request TRIG line %d\n", TRIG_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    echo_line = gpiod_chip_request_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to request ECHO line %d\n", ECHO_PIN);
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return 1;
    }

    led_line = gpiod_chip_request_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to request LED line %d\n", LED_PIN);
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure lines
    ret = gpiod_line_request_config(trig_line, &trig_req);
    if (ret < 0) {
        fprintf(stderr, "Failed to configure TRIG line %d: %s\n", TRIG_PIN, strerror(errno));
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_config(echo_line, &echo_req);
    if (ret < 0) {
        fprintf(stderr, "Failed to configure ECHO line %d: %s\n", ECHO_PIN, strerror(errno));
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_config(led_line, &led_req);
    if (ret < 0) {
        fprintf(stderr, "Failed to configure LED line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Trigger pulse
        gpiod_line_set_value(trig_line, 1);
        usleep(1000); // 1ms
        gpiod_line_set_value(trig_line, 0);

        // Wait for echo
        int echo_state = 0;
        int start_time = 0;
        int end_time = 0;

        // Wait for echo to go high
        for (int i = 0; i < TIMEOUT_MS; i++) {
            if (gpiod_line_get_value(echo_line) == 1) {
                start_time = i;
                break;
            }
            usleep(1000); // 1ms
        }

        if (start_time == 0) {
            // No echo received
            printf("No echo received\n");
            gpiod_line_set_value(led_line, 0);
            usleep(POLLING_INTERVAL_MS * 1000);
            continue;
        }

        // Wait for echo to go low
        for (int i = start_time; i < TIMEOUT_MS; i++) {
            if (gpiod_line_get_value(echo_line) == 0) {
                end_time = i;
                break;
            }
            usleep(1000); // 1ms
        }

        if (end_time == 0) {
            // Echo did not return
            printf("Echo did not return\n");
            gpiod_line_set_value(led_line, 0);
            usleep(POLLING_INTERVAL_MS * 1000);
            continue;
        }

        // Calculate distance
        int pulse_duration = end_time - start_time;
        double distance_cm = (pulse_duration * 0.0343) / 2;

        if (distance_cm < 0 || distance_cm > MAX_DISTANCE_CM) {
            printf("Distance out of range: %.2f cm\n", distance_cm);
            gpiod_line_set_value(led_line, 0);
        } else {
            printf("Distance: %.2f cm\n", distance_cm);
            gpiod_line_set_value(led_line, 1);
        }

        usleep(POLLING_INTERVAL_MS * 1000);
    }

    // Cleanup
    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>

#define GPIO_PIN 16
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    // Set up signal handler for graceful exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set GPIO mode to output
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    // Set PWM parameters
    if (gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(GPIO_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    // Start PWM
    if (gpioPWM(GPIO_PIN, PWM_RANGE / 2) < 0) {
        fprintf(stderr, "Failed to start PWM on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    // Report initial state
    printf("PWM started on GPIO %d (BCM), frequency: %d Hz, duty cycle: 50%%\n", GPIO_PIN, PWM_FREQUENCY);

    // Wait for signal to exit
    while (running) {
        sleep(1);
    }

    // Stop PWM
    gpioPWM(GPIO_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

