#include <stdio.h>
#include <stdlib.h>
#include <libgpiod.h>
#include <unistd.h>
#include <signal.h>

#define GPIO_PINS 7
int pin_numbers[GPIO_PINS] = {4, 17, 18, 22, 23, 24, 27};
int pin_states[GPIO_PINS] = {0};

struct gpiod_line *lines[GPIO_PINS];
struct gpiod_chip *chip;
int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void cleanup() {
    for (int i = 0; i < GPIO_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("GPIO cleanup completed.\n");
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int i;

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip.\n");
        return 1;
    }

    // Initialize all GPIO lines
    for (i = 0; i < GPIO_PINS; i++) {
        line = gpiod_chip_get_line(chip, pin_numbers[i]);
        if (!line) {
            fprintf(stderr, "Failed to get line for GPIO %d.\n", pin_numbers[i]);
            cleanup();
            return 1;
        }

        if (gpiod_line_request_output(line, "gpio-output", 0) < 0) {
            fprintf(stderr, "Failed to request line %d as output.\n", pin_numbers[i]);
            cleanup();
            return 1;
        }

        lines[i] = line;
    }

    // Set initial states and report
    for (i = 0; i < GPIO_PINS; i++) {
        if (gpiod_line_set_value(lines[i], 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d to 1.\n", pin_numbers[i]);
            cleanup();
            return 1;
        }
        pin_states[i] = 1;
    }

    printf("GPIO output set to 1 on pins: ");
    for (i = 0; i < GPIO_PINS; i++) {
        printf("%d ", pin_numbers[i]);
    }
    printf("\n");

    // Wait for signal to exit
    while (running) {
        usleep(100000); // 100ms
    }

    cleanup();
    return 0;
}

