#include <libgpiod.h>

#define GPIO_PIN 18
#define INTERVAL 500000000 /* 0.5 seconds in nanoseconds */

int main() {
    struct gpiod_line *line;
    struct gpiod_line_request_config req;
    int ret;

    /* Initialize line request configuration */
    gpiod_line_request_config_init(&req);
    req.consumer = "gpio-test";
    req.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;
    req.output = 1;
    req.default_value = 0;

    /* Open the GPIO line */
    line = gpiod_line_get("gpiochip4", GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_PIN);
        return EXIT_FAILURE;
    }

    /* Request the line */
    ret = gpiod_line_request_output(line, &req);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    /* Main loop */
    while (1) {
        /* Set the line to high */
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO line %d to high: %s\n", GPIO_PIN, strerror(errno));
            gpiod_line_release(line);
            return EXIT_FAILURE;
        }
        printf("GPIO %d set to high\n", GPIO_PIN);
        fflush(stdout);

        /* Wait for 0.5 seconds */
