            return EXIT_FAILURE;
        }
        printf("GPIO %d set to low\n", GPIO_PIN);
        fflush(stdout);

        /* Wait for 0.5 seconds */
        usleep(INTERVAL);
    }

    /* Clean up on exit */
    gpiod_line_release(line);
    return EXIT_SUCCESS;
}

