    struct gpiod_line *line;
    struct gpiod_line_request_config req;
    int ret;

    // Initialize line request configuration
    memset(&req, 0, sizeof(req));
    req.consumer = "gpio-test";
    req.line_offset = GPIO_PIN;
    req.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;

    // Open the GPIO line
    line = gpiod_line_get("gpiochip0", GPIO_PIN);
