        gpiod_line_put(line);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Toggle the output state
        int state = gpiod_line_get_value(line);
        ret = gpiod_line_set_value(line, (state + 1) % 2);
