#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE B115200
#define TIMEOUT_MS 100
#define BUFFER_SIZE 128

int uart_fd = -1;
volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

void close_uart() {
    if (uart_fd >= 0) {
        close(uart_fd);
        uart_fd = -1;
    }
}

void setup_uart() {
    struct termios tty;
    struct termios saved_tty;

    if ((uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY)) < 0) {
        perror("Failed to open UART device");
        exit(EXIT_FAILURE);
    }

    if (tcgetattr(uart_fd, &tty) != 0) {
        perror("Failed to get terminal attributes");
        close_uart();
        exit(EXIT_FAILURE);
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag &= ~PARENB;        // No parity
    tty.c_cflag &= ~CSTOPB;        // 1 stop bit
    tty.c_cflag &= ~CSIZE;         // Clear data size mask
    tty.c_cflag |= CS8;            // 8 bits per byte
    tty.c_cflag &= ~CRTSCTS;       // No hardware flow control
    tty.c_cflag |= CREAD | CLOCAL; // Enable receiver, ignore modem control lines

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG); // Disable canonical mode
    tty.c_oflag &= ~OPOST; // Disable output processing
    tty.c_cc[VTIME] = 0;   // Wait 0 seconds for input
    tty.c_cc[VMIN] = 1;    // Read at least 1 character

    if (tcsetattr(uart_fd, TCSAFLUSH, &tty) != 0) {
        perror("Failed to set terminal attributes");
        close_uart();
        exit(EXIT_FAILURE);
    }

    if (tcgetattr(uart_fd, &saved_tty) != 0) {
        perror("Failed to save terminal attributes");
        close_uart();
        exit(EXIT_FAILURE);
    }
}

void read_uart() {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    bytes_read = read(uart_fd, buffer, sizeof(buffer));
    if (bytes_read < 0) {
        perror("UART read error");
        close_uart();
        exit(EXIT_FAILURE);
    } else if (bytes_read == 0) {
        fprintf(stderr, "No data received from device\n");
        close_uart();
        exit(EXIT_FAILURE);
    }

    buffer[bytes_read] = '\0';
    printf("Received: %s\n", buffer);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to set signal handler");
        exit(EXIT_FAILURE);
    }

    setup_uart();

    while (running) {
        read_uart();
        usleep(100000); // 0.1 seconds
    }

    close_uart();
    return 0;
}

