    ret = gpiod_line_request_output(trig_line, "trig", GPIO_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request TRIG line %d as output: %s\n", TRIG_PIN, strerror(errno));
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure ECHO as input
    ret = gpiod_line_request_input(echo_line, "echo");
    if (ret < 0) {
        fprintf(stderr, "Failed to request ECHO line %d as input: %s\n", ECHO_PIN, strerror(errno));
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure GND as output (optional, but for completeness)
    ret = gpiod_line_request_output(gnd_line, "gnd", GPIO_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GND line %d as output: %s\n", GND_PIN, strerror(errno));
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set GND to low (optional, but for completeness)
    ret = gpiod_line_set_value(gnd_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GND line %d: %s\n", GND_PIN, strerror(errno));
        gpiod_line_release(gnd_line);
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Send trigger pulse
    ret = gpiod_line_set_value(trig_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set TRIG line %d: %s\n", TRIG_PIN, strerror(errno));
        gpiod_line_release(gnd_line);
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return 1;
    }

    usleep(10); // Trigger pulse duration: 10 microseconds

    ret = gpiod_line_set_value(trig_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set TRIG line %d: %s\n", TRIG_PIN, strerror(errno));
        gpiod_line_release(gnd_line);
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Wait for echo to go high
    int echo_high = 0;
    int start_time = 0;
    int end_time = 0;

    for (int i = 0; i < MAX_WAIT_TIME_MS; i++) {
        usleep(1000); // 1 ms
        if (gpiod_line_get_value(echo_line) == 1) {
            echo_high = 1;
            start_time = i;
            break;
        }
    }

    if (!echo_high) {
        fprintf(stderr, "No echo signal detected\n");
        gpiod_line_release(gnd_line);
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Wait for echo to go low
    for (int i = start_time; i < MAX_WAIT_TIME_MS; i++) {
        usleep(1000); // 1 ms
        if (gpiod_line_get_value(echo_line) == 0) {
            end_time = i;
            break;
        }
    }

    if (end_time == start_time) {
        fprintf(stderr, "Echo signal too short\n");
        gpiod_line_release(gnd_line);
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Calculate pulse duration in microseconds
    int pulse_duration = (end_time - start_time) * 1000;

    if (pulse_duration > MAX_PULSE_TIME_US) {
        fprintf(stderr, "Pulse duration too long: %d us\n", pulse_duration);
        gpiod_line_release(gnd_line);
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Convert to distance in centimeters
    double distance_cm = (double)pulse_duration * 0.034 / 2;

    printf("Distance: %.2f cm\n", distance_cm);

    // Release resources
    gpiod_line_release(gnd_line);
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return 0;
}

