#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define INTERVAL 2000000  // 0.2 seconds in microseconds

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    // Set up GPIO 18 as PWM output
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMFrequency(GPIO_PIN, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for termination
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        // Set PWM duty cycle (0-100%)
        if (gpioPWM(GPIO_PIN, 50) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", GPIO_PIN);
            gpioTerminate();
            return 1;
        }

        // Report state to stdout
        printf("PWM applied to GPIO %d (duty cycle 50%%)\n", GPIO_PIN);
        fflush(stdout);

        // Wait for interval
        usleep(INTERVAL);
    }

    // Clean up
    gpioPWM(GPIO_PIN, 0);  // Turn off PWM
    gpioTerminate();

    return 0;
}

