    ret = gpiod_line_request_output(line_18, "gpio-out-18", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line 18 as output: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure GPIO 23 as output
    line_23 = gpiod_chip_get_line(chip, GPIO_PIN_23);
    if (!line_23) {
        fprintf(stderr, "Failed to get line for GPIO 23\n");
        gpiod_line_release(line_18);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line_23, "gpio-out-23", 0);
    if (ret < 0) {
