#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_ACCEL_XOUT_L 0x3C
#define MPU6050_ACCEL_YOUT_H 0x3D
#define MPU6050_ACCEL_YOUT_L 0x3E
#define MPU6050_ACCEL_ZOUT_H 0x3F
#define MPU6050_ACCEL_ZOUT_L 0x40
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_GYRO_XOUT_L 0x44
#define MPU6050_GYRO_YOUT_H 0x45
#define MPU6050_GYRO_YOUT_L 0x46
#define MPU6050_GYRO_ZOUT_H 0x47
#define MPU6050_GYRO_ZOUT_L 0x48

typedef struct {
    int16_t ax;
    int16_t ay;
    int16_t az;
    int16_t gx;
    int16_t gy;
    int16_t gz;
} mpu6050_data_t;

int i2c_fd = -1;
volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

void close_i2c() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int open_i2c() {
    int fd = -1;
    char *filename = I2C_BUS;

    fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

void read_mpu6050(mpu6050_data_t *data) {
    uint8_t buffer[14];

    if (read(i2c_fd, buffer, 14) != 14) {
        perror("Failed to read from MPU6050");
        return;
    }

    data->ax = (int16_t)(buffer[0] << 8 | buffer[1]);
    data->ay = (int16_t)(buffer[2] << 8 | buffer[3]);
    data->az = (int16_t)(buffer[4] << 8 | buffer[5]);
    data->gx = (int16_t)(buffer[6] << 8 | buffer[7]);
    data->gy = (int16_t)(buffer[8] << 8 | buffer[9]);
    data->gz = (int16_t)(buffer[10] << 8 | buffer[11]);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open_i2c();
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    mpu6050_data_t data;

    while (running) {
        read_mpu6050(&data);

        printf("Accel: X=%d Y=%d Z=%d  Gyro: X=%d Y=%d Z=%d\n",
               data.ax, data.ay, data.az, data.gx, data.gy, data.gz);

        sleep(1);
    }

    close_i2c();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define INTERVAL 600000000  // 0.6 seconds in nanoseconds

static volatile int running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_line *line;
    struct gpiod_line_request_config req_config;
    struct gpiod_line_settings settings;
    int ret;

    // Set up signal handler for graceful exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize line request configuration
    gpiod_line_request_config_init(&req_config);
    req_config.consumer = "gpio_output";
    req_config.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;

    // Initialize line settings
    gpiod_line_settings_init(&settings);
    settings.direction = GPIOD_LINE_DIRECTION_OUTPUT;
    settings.output = GPIOD_LINE_OUTPUT_ACTIVE_LOW;

    // Open the GPIO line
    line = gpiod_line_get("gpiochip0", GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        exit(EXIT_FAILURE);
    }

    // Request the line
    ret = gpiod_line_request_config(line, &req_config, &settings);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", gpiod_strerror(ret));
        gpiod_line_put(line);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (running) {
        // Set the output to high (active low, so set to 0)
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO value: %s\n", gpiod_strerror(ret));
            break;
        }

        // Report the state
        printf("GPIO %d set to HIGH\n", GPIO_PIN);
        fflush(stdout);

        // Wait for the interval
        usleep(INTERVAL);

        // Set the output to low (active low, so set to 1)
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO value: %s\n", gpiod_strerror(ret));
            break;
        }

        // Report the state
        printf("GPIO %d set to LOW\n", GPIO_PIN);
        fflush(stdout);

        // Wait for the interval
        usleep(INTERVAL);
    }

    // Clean up
    gpiod_line_put(line);
    printf("GPIO %d released\n", GPIO_PIN);
    fflush(stdout);

    return 0;
}

